/plugins/tasks/static/tasks.css.body:
/* The task system's look on every page: its ticket states, the ticket cards of the Tasks panel,
   the ticket drawer and its markdown, the paused control. Loaded by the Tickets page (which adds
   tickets.css for its graph) and by tasks.js on Orchestra's other pages (Orchestra's style.css
   has the frame: panels, drawers, .kv, .note, .empty, button.ctl). */
:root {
  --OPEN:#6b7280; --PREPARING:#0d9488; --BLOCKED:#f0883e; --IN_PROGRESS:#3b82f6; --READY_FOR_REVIEW:#7c3aed; --IN_REVIEW:#a855f7; --REJECTED:#ef4444;
  --APPROVED:#d97706; --IN_EXTERNAL_REVIEW:#0ea5e9; --MERGING:#f59e0b; --DONE:#16a34a; --CANCELLED:#374151;
}
.work { background:var(--panel2); border:1px solid var(--border); border-left:4px solid var(--c); border-radius:10px; padding:10px 12px; margin-bottom:8px; cursor:pointer }
.work:hover { background:var(--panel3) } .work .top { display:flex; justify-content:space-between; gap:8px; align-items:center; min-width:0 }
.work .top > span:first-child { flex:1 1 auto; min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap }
.work .id { font-family:var(--mono); font-weight:700; color:var(--c); text-decoration:underline dotted; text-underline-offset:3px } .work .title { font-weight:600 }
.work .right { display:flex; align-items:center; gap:8px; flex:none; white-space:nowrap }
.work .turns { font-family:var(--mono); font-size:11px; color:#fcd34d; background:#3a2e0a; border:1px solid #6b5313; border-radius:999px; padding:1px 7px; cursor:help; white-space:nowrap; flex:none }
.work .lane { margin-top:6px; font-size:12px; color:var(--text2) } .work .lane .msg { display:block; white-space:nowrap; overflow:hidden; text-overflow:ellipsis }
.work, .work > *, .work .lane > * { min-width:0 }
.pill { display:inline-block; padding:2px 8px; border-radius:999px; font-size:10.5px; font-weight:700; letter-spacing:.04em; color:#0b0d12; background:var(--c); white-space:nowrap }
.alert { border-radius:10px; padding:12px 14px; margin:0 0 14px; border:1px solid } .alert h4 { margin:0 0 6px; font-size:11px; text-transform:uppercase; letter-spacing:.08em }
.alert.blocked { background:#2a1a0e; border-color:#c2410c; color:#fed7aa } .alert.rejected { background:#2a1215; border-color:#b91c1c; color:#fecaca }
.alert.waiting { background:#141a26; border-color:#1e3a8a; color:#bfdbfe } .alert .md { color:inherit }
.md { font-size:13px; line-height:1.5 } .md p { margin:6px 0 } .md h1,.md h2,.md h3 { font-size:13px; text-transform:none; letter-spacing:0; color:var(--text); margin:10px 0 4px; display:block }
.md ul,.md ol { padding-left:20px; margin:4px 0 } .md li { margin:2px 0 } .md code { background:#07090d; border:1px solid var(--border); border-radius:4px; padding:0 4px; font-size:12px }
.md pre { padding:0; border:1px solid var(--border); background:#07090d } .md pre code { display:block; padding:8px; border:0; background:#0d1117; font-size:12px; overflow:auto }
.md blockquote { border-left:3px solid var(--border); margin:6px 0; padding:2px 10px; color:var(--muted) } .md table { border-collapse:collapse } .md td,.md th { border:1px solid var(--border); padding:3px 8px }
.md strong { color:#fff }
button.ctl.paused { color:#fde68a; border-color:#92400e; background:#2a1f0e }

/plugins/agents/static/agents.css.body:
/* The agents' look: role colours, the agent rows and the ticket cards they work on (.awork: the task
   system's cards are .work, with a lane of their own), session chips,
   transcripts, the chat and rendered markdown. Loaded by the Agents page and the agents' scripts on Orchestra's
   pages. The ticket-state colours are the task system's names, kept here so an agent's card is
   coloured without the task system's stylesheet. */
:root {
  --OPEN:#6b7280; --BLOCKED:#f0883e; --IN_PROGRESS:#3b82f6; --READY_FOR_REVIEW:#7c3aed; --IN_REVIEW:#a855f7; --REJECTED:#ef4444;
  --APPROVED:#d97706; --MERGING:#f59e0b; --DONE:#16a34a; --CANCELLED:#374151;
  --r-supervisor:#c084fc; --r-coordinator:#38bdf8; --r-worker:#60a5fa; --r-reviewer:#e879f9;
}
.msg.inprogress { border:1px dashed #1d4ed8; opacity:.9 }
.msg.marker { background:#1a1a22; border:1px dashed var(--border2); color:var(--text2); font-size:12px } .msg.marker.session_timed_out, .msg.marker.session_error { border-color:#92400e; color:#fcd34d } .msg.marker.session_interrupted, .msg.marker.agent_crashed, .msg.marker.agent_crash_loop { border-color:#7f1d1d; color:#fca5a5 }
details.started { margin:10px 0 } details.started summary { cursor:pointer; font-size:12px; color:var(--text2) } details.started .prompt { border:1px solid var(--border); border-radius:8px; padding:10px 14px; background:#0b0e14; max-height:50vh; overflow:auto; margin-top:6px }
/* ---- agents ---- */
.agent { display:grid; grid-template-columns:22px auto 1fr auto; gap:8px; align-items:center; background:var(--panel2); border:1px solid var(--border); border-radius:8px; padding:5px 10px; margin-bottom:4px; cursor:pointer }
.agent:hover { border-color:var(--border2); background:var(--panel3) }
.agent .av { width:22px; height:22px; border-radius:6px; display:grid; place-items:center; font-weight:800; font-size:11px; color:#0b0d12; background:var(--rc) }
.agent .name { font-weight:700; font-size:12.5px; white-space:nowrap }
.agent .say { font-size:11.5px; color:var(--text2); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; font-style:italic }
.chip { display:inline-flex; align-items:center; gap:6px; font-size:11px; font-weight:600; padding:3px 8px; border-radius:999px; background:var(--panel3); color:var(--text2); border:1px solid var(--border); white-space:nowrap }
.chip .dot { width:7px; height:7px; border-radius:50%; background:#5b6473; margin:0 }
.chip.working { color:#bfdbfe; border-color:#1d4ed8 } .chip.working .dot { background:#3b82f6; animation:pulse 1.4s infinite }
.chip.resident { color:#bbf7d0; border-color:#166534 } .chip.resident .dot { background:#22c55e }
.chip.down { color:#fecaca; border-color:#7f1d1d } .chip.down .dot { background:#ef4444 }
@keyframes pulse { 50% { opacity:.3 } }
.awork { background:var(--panel2); border:1px solid var(--border); border-left:4px solid var(--c); border-radius:10px; padding:10px 12px; margin-bottom:8px; cursor:pointer }
.awork:hover { background:var(--panel3) } .awork .top { display:flex; justify-content:space-between; gap:8px; align-items:center; min-width:0 }
.awork .top > span:first-child { min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap }
.awork .id { font-family:var(--mono); font-weight:700; color:var(--c); text-decoration:underline dotted; text-underline-offset:3px } .awork .title { font-weight:600 }
.awork .right { display:flex; align-items:center; gap:8px; flex:none; white-space:nowrap }
.awork .turns { font-family:var(--mono); font-size:11px; color:#fcd34d; background:#3a2e0a; border:1px solid #6b5313; border-radius:999px; padding:1px 7px; cursor:help; white-space:nowrap; flex:none }
.awork .top > span:first-child { flex:1 1 auto }
.awork .lane { display:grid; grid-template-columns:62px 1fr auto; gap:8px; align-items:center; margin-top:6px; font-size:12px; color:var(--text2) }
.awork .lane .who { color:var(--muted); font-size:10.5px; text-transform:uppercase; letter-spacing:.05em } .awork .lane .msg { white-space:nowrap; overflow:hidden; text-overflow:ellipsis }
.awork .pill { display:inline-block; padding:2px 8px; border-radius:999px; font-size:10.5px; font-weight:700; letter-spacing:.04em; color:#0b0d12; background:var(--c); white-space:nowrap }
/* ---- transcripts and the chat ---- */
.msg { border-left:3px solid var(--border); padding:4px 10px; margin:8px 0 } .msg.user { border-color:var(--accent) } .msg.assistant { border-color:#22c55e } .msg.toolResult { border-color:#4b5563; color:var(--text2) }
.tc { margin:6px 0 } .tc .r { color:var(--muted); font-size:11px } .tc pre { margin:2px 0 } .msg.toolResult.err { border-color:#ef4444 } .msg pre.term { max-height:40vh; min-height:0 }
.chat { position:sticky; bottom:-18px; background:var(--panel2); padding:10px 0 4px; margin-top:12px; border-top:1px solid var(--border); display:flex; gap:8px; align-items:flex-start; flex-wrap:wrap }
.chat textarea { flex:1; min-width:0; background:var(--bg); color:var(--text); border:1px solid var(--border2); border-radius:8px; padding:8px; font:13px/1.4 inherit; resize:vertical }
.chat button { background:var(--accent); color:#000; border:0; border-radius:8px; padding:8px 14px; font-weight:700; cursor:pointer } .chat button:disabled,.chat textarea:disabled { opacity:.5 }
.chat .empty { flex-basis:100% }
.chat.top { position:static; border-top:0; border-bottom:1px solid var(--border); padding:4px 0 10px; margin:10px 0 }
@media (max-width: 900px) { .chat { bottom:-14px } }   /* Orchestra's drawer has 14px of padding there, not 18px */
.chip.waiting { color:#fde68a; border-color:#92400e } .chip.waiting .dot { background:#f59e0b; animation:pulse 2.4s infinite }
.chip.archived { color:var(--muted) }
.msg .r { font-size:11px; color:var(--muted) }
.agent, .agent > *, .awork, .awork > *, .awork .lane > * { min-width:0 }
/* ---- markdown (md() in agents.js) ---- */
.md { font-size:13px; line-height:1.5 } .md p { margin:6px 0 } .md h1,.md h2,.md h3 { font-size:13px; text-transform:none; letter-spacing:0; color:var(--text); margin:10px 0 4px; display:block }
.md ul,.md ol { padding-left:20px; margin:4px 0 } .md li { margin:2px 0 } .md code { background:#07090d; border:1px solid var(--border); border-radius:4px; padding:0 4px; font-size:12px }
.md pre { padding:0; border:1px solid var(--border); background:#07090d } .md pre code { display:block; padding:8px; border:0; background:#0d1117; font-size:12px; overflow:auto }
.md blockquote { border-left:3px solid var(--border); margin:6px 0; padding:2px 10px; color:var(--muted) } .md table { border-collapse:collapse } .md td,.md th { border:1px solid var(--border); padding:3px 8px }
.md strong { color:#fff }
/* ---- a wake-up in a transcript, and one turn read at a glance (renderTurn: the ticket drawer's agent sessions) ---- */
details.msg.marker.wake > summary { cursor:pointer } details.msg.marker.wake .prompt { max-height:50vh; overflow:auto; margin-top:6px }
.tt-prompt, .tt-tool { margin:4px 0; font-size:12px } .tt-prompt > summary, .tt-tool > summary { cursor:pointer; color:var(--text2); white-space:nowrap; overflow:hidden; text-overflow:ellipsis }
.tt-prompt .prompt { border:1px solid var(--border); border-radius:8px; padding:8px 12px; background:#0b0e14; max-height:40vh; overflow:auto; margin-top:4px }
.tt-tool { border-left:2px solid #4b5563; padding-left:8px } .tt-tool.err { border-left-color:#ef4444 } .tt-tool summary code { font-size:11px; color:var(--muted) }
.tt-tool pre { max-height:30vh; min-height:0; overflow:auto; margin:4px 0; font-size:11.5px }
.tt-say { border-left:3px solid #22c55e; padding:2px 10px; margin:6px 0 } .tt-say.last { background:rgba(34,197,94,.06) }
/* the ticket drawer's agent sessions (ticket-sessions.js) */
.tks { margin:10px 0 4px } .tks .tks-head { display:flex; align-items:baseline; gap:8px } .tks .tks-head .muted { font-size:11px }
.tks-row { border:1px solid var(--border); border-left:4px solid var(--rc, #60a5fa); border-radius:8px; padding:6px 10px; margin:6px 0; background:var(--panel2) }
.tks-row .tks-top { display:grid; grid-template-columns:auto auto 1fr auto auto; gap:8px; align-items:center; font-size:12px; min-width:0 }
.tks-row .who { font-weight:700; white-space:nowrap } .tks-row .what { color:var(--muted); white-space:nowrap } .tks-row .when { color:var(--muted); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; min-width:0 }
.tks-row .out { font-size:10.5px; font-weight:700; padding:2px 8px; border-radius:999px; background:var(--oc, #374151); color:#0b0d12; white-space:nowrap }
.tks-row .out.running { animation:pulse 1.4s infinite }
.tks-row .say { font-size:12px; color:var(--text2); margin-top:4px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis }
.tks-row .acts { display:flex; gap:6px } .tks-row .acts button { font-size:11px; padding:2px 8px; border-radius:6px; border:1px solid var(--border2); background:var(--panel3); color:var(--text); cursor:pointer }
.tks-row .tks-turn { border-top:1px dashed var(--border); margin-top:6px; padding-top:4px }
@media (max-width:640px) { .tks-row .tks-top { grid-template-columns:1fr auto; } .tks-row .what, .tks-row .when { grid-column:1 } }
/* the machine cards' finished sessions (machine-cards.js) */
.tkc-past { margin-top:6px } .tkc-past > summary { cursor:pointer; font-size:11px; color:var(--muted) }
.tkc-past .row { display:grid; grid-template-columns:auto auto 1fr auto; gap:8px; font-size:11.5px; padding:3px 4px; cursor:pointer; border-radius:6px; align-items:center; min-width:0 }
.tkc-past .row:hover { background:var(--panel3) } .tkc-past .row .id { font-family:var(--mono); font-weight:700 } .tkc-past .row > span { min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap }

/static/style.css?v=1793227874.body:
/* Orchestra's web UI. A package's own look (its states, cards, drawers and colours) is in the
   package's stylesheet, not here. */
:root {
  --bg:#0b0d12; --panel:#12151c; --panel2:#181c25; --panel3:#1f2430; --border:#262b37; --border2:#333a49;
  --text:#e7eaf0; --text2:#aeb6c4; --muted:#6f7889; --accent:#6ea8fe;
  --mono:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;
}
* { box-sizing:border-box }
body { margin:0; background:var(--bg); color:var(--text); font:13px/1.45 -apple-system,"Segoe UI",Helvetica,Arial,sans-serif }
a { color:var(--accent) }
nav { display:flex; align-items:center; gap:18px; padding:0 16px; height:44px; border-bottom:1px solid var(--border); background:var(--panel) }
nav a { color:var(--muted); text-decoration:none; font-weight:600; padding:12px 0; border-bottom:2px solid transparent } nav a.on { color:var(--text); border-color:var(--accent) }
.muted { color:var(--muted) } .num { font-family:var(--mono); font-variant-numeric:tabular-nums }
.layout { display:grid; grid-template-columns:repeat(3, minmax(0, 1fr)); height:calc(100vh - 44px) }
.col { overflow:auto; padding:14px 16px; border-right:1px solid var(--border) } .col:last-child { border-right:0 }
h2 { font-size:11px; text-transform:uppercase; letter-spacing:.08em; color:var(--muted); margin:16px 0 8px; display:flex; justify-content:space-between }
h2 .count { color:var(--text2); font-family:var(--mono); font-weight:500 }
h2 .hctl { display:flex; gap:8px; align-items:center; text-transform:none; letter-spacing:0; font-weight:400; white-space:nowrap } h2 .hctl .ctl { margin:0; white-space:nowrap }
.empty { color:var(--muted); font-size:12px; padding:10px 12px; border:1px dashed var(--border); border-radius:8px }
.page { padding:10px; height:calc(100vh - 44px); overflow:auto }



/* ---- host ---- */
.panel { background:var(--panel2); border:1px solid var(--border); border-radius:10px; padding:12px; margin-bottom:12px }
.kv { display:grid; grid-template-columns:auto 1fr; gap:3px 12px; font-size:12px } .kv div:nth-child(odd) { color:var(--muted) }
.lbl-row { display:flex; justify-content:space-between; font-size:11px; color:var(--muted); margin:2px 0 }
.gpu { width:100%; height:64px; display:block; background:var(--panel); border:1px solid var(--border); border-radius:8px; min-height:0 }
#gpu-line { fill:none; stroke:#2dd4bf; stroke-width:1.6; vector-effect:non-scaling-stroke } #gpu-area { fill:#2dd4bf; fill-opacity:.14 }
#gpu-cursor { stroke:#2dd4bf; stroke-opacity:.5; stroke-dasharray:2 2; vector-effect:non-scaling-stroke }
.cores { display:flex; align-items:stretch; gap:3px; height:52px; width:100%; padding:4px 0 }
.core { flex:1 1 0; height:100%; background:var(--panel); border-radius:2px 2px 0 0; position:relative; min-width:3px }
.core i { position:absolute; left:0; right:0; bottom:0; display:block; border-radius:2px 2px 0 0; transition-property:height,background-color; transition-timing-function:linear; transition-duration:2s }
.meters { display:flex; gap:12px; margin-top:8px } .meter { flex:1 1 0; min-width:0 }
.meter .bar { height:8px; background:var(--panel); border-radius:4px; overflow:hidden } .meter .bar i { display:block; height:100%; width:0; transition:width .4s }
.meter .lbl { display:flex; justify-content:space-between; font-size:11px; color:var(--muted); margin-bottom:3px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis }
#mem-bar { background:linear-gradient(90deg,#7c3aed,#c084fc) } #disk-bar { background:linear-gradient(90deg,#d97706,#fbbf24) }
.env { border-left:4px solid var(--ec, var(--muted)) }
.env .led { display:inline-block; width:9px; height:9px; border-radius:50%; background:var(--ec, var(--muted)); margin-right:6px; box-shadow:0 0 8px var(--ec, transparent) }
.term { background:#07090d; border:1px solid var(--border); border-radius:8px; padding:8px 10px; font:11.5px/1.45 var(--mono); color:#c9d1d9; white-space:pre-wrap; min-height:180px; max-height:40vh; overflow:auto }

/* ---- log highlighting ---- */
.lg-ts { color:#8b949e } .lg-tag { color:#79c0ff } .lg-err { color:#ff7b72; font-weight:600 } .lg-warn { color:#d29922 }
.lg-ok { color:#3fb950 } .lg-method { color:#d2a8ff; font-weight:600 } .lg-url { color:#58a6ff; text-decoration:underline dotted }
.lg-str { color:#a5d6ff } .lg-path { color:#ffa657 } .lg-key { color:#e3b341 } .lg-num { color:#f2cc60 }

/* ---- drawers ---- */
.overlay { position:fixed; inset:0; background:rgba(0,0,0,.6); display:none; align-items:center; justify-content:center; z-index:9 }
.overlay.open { display:flex } .drawer { width:min(940px,94vw); max-height:88vh; overflow:auto; background:var(--panel2); border:1px solid var(--border2); border-radius:12px; padding:18px 20px }
.drawer h3 { margin:0 0 10px; display:flex; align-items:center; gap:10px; flex-wrap:wrap }
pre { background:#07090d; border:1px solid var(--border); border-radius:8px; padding:8px 10px; white-space:pre-wrap; font-size:12px; max-height:50vh; overflow:auto }
.note { border-top:1px solid var(--border); padding:8px 0; font-size:12px } .note b { color:var(--muted) }

/* ---- mobile ---- */
@media (max-width: 900px) {
  nav { height:auto; flex-wrap:wrap; gap:10px 14px; padding:8px 12px } nav a { padding:6px 0 } nav #conn { margin-left:auto }
  .layout { display:block; height:auto }
  .col { display:none; border-right:0; padding:12px; height:auto; overflow:visible } .col.on { display:block }
  .page { padding:6px; height:auto }
  .overlay { align-items:stretch } .drawer { width:100vw; max-height:100vh; height:100vh; border-radius:0; padding:14px }
  .kv { grid-template-columns:auto 1fr }
}
nav #proj { min-width:0; flex:1; overflow:hidden; text-overflow:ellipsis; white-space:nowrap }
/* one row on phones: the links that do not fit scroll sideways (the page itself never does), so a
   page a plugin adds is never cut off out of reach */
@media (max-width: 900px) { html, body { overflow-x:hidden; max-width:100vw } nav { flex-wrap:nowrap; overflow-x:auto; scrollbar-width:none } nav a { flex:none } nav #proj { font-size:11px; min-width:80px } }
/* range selectors in chart headers */
select.range { background:var(--panel3); color:var(--text2); border:1px solid var(--border); border-radius:5px; font:inherit; font-size:10.5px; padding:1px 4px; margin-left:4px; text-transform:none; letter-spacing:0; cursor:pointer }
/* operator controls */
button.ctl { background:var(--panel3); color:var(--text2); border:1px solid var(--border2); border-radius:6px; font:inherit; font-size:11px; padding:2px 8px; cursor:pointer; margin-left:6px }
button.ctl:hover { color:var(--text); border-color:var(--accent) }
/* chart hover */
.tip { position:fixed; z-index:20; pointer-events:none; background:#0b0d12; border:1px solid var(--border2); border-radius:6px; padding:6px 9px; font-size:11.5px; color:var(--text2); box-shadow:0 4px 16px rgba(0,0,0,.5); font-family:var(--mono) } .tip b { color:var(--text) }

/* core services */
.core .chead { display:flex; justify-content:space-between; align-items:center; margin-bottom:8px }
.core .types { display:flex; flex-wrap:wrap; gap:4px; margin:8px 0 2px } .core .ty { font-size:10.5px; color:var(--text2); background:var(--panel3); border:1px solid var(--border); border-radius:999px; padding:1px 7px }
.core .sl { font-size:10.5px; text-transform:uppercase; letter-spacing:.05em; color:var(--muted); margin-top:10px }
svg.spark { width:100%; height:34px; min-height:0; display:block; margin-top:3px } svg.spark .l { fill:none; stroke:#94a3b8; stroke-width:1.4; vector-effect:non-scaling-stroke } svg.spark .a { fill:#94a3b81a }
svg.spark.blue .l { stroke:#6ea8fe } svg.spark.blue .a { fill:#6ea8fe22 } svg.spark.amber .l { stroke:#fbbf24 } svg.spark.amber .a { fill:#fbbf2422 }
.spark.empty { font-size:11px; color:var(--muted); padding:8px 0 }
.core .probe { margin-top:10px; font-size:11.5px; padding:6px 8px; border-radius:6px } .core .probe.ok { background:#0f2a1a; color:#bbf7d0; border:1px solid #166534 } .core .probe.bad { background:#2a0f0f; color:#fecaca; border:1px solid #7f1d1d }
.corestrip { display:flex; gap:8px; align-items:center; font-size:12px; color:var(--text2); text-decoration:none; padding:8px 12px } .corestrip:hover { border-color:var(--accent) }
.corestrip .cled { display:inline-block; width:8px; height:8px; border-radius:50%; margin-left:6px }
.layout.two { grid-template-columns:repeat(2, minmax(0, 1fr)) }

/* ---- network graphs (netgraph.js): the event map and the stock-and-flow model ---- */
svg.netgraph { display:block; width:100%; min-height:0; font-size:11px; cursor:grab; background:var(--panel2); border-radius:10px }
.ng-node { cursor:pointer } .ng-node text { pointer-events:none }
.ng-initial { fill:#0b0d12; font-weight:800; font-size:15px }
.ng-name { fill:var(--text); font-weight:600; font-size:11.5px; paint-order:stroke; stroke:var(--panel2); stroke-width:3px }
.ng-sub { fill:var(--muted); font-size:9.5px; paint-order:stroke; stroke:var(--panel2); stroke-width:3px }
.ng-caption { fill:var(--muted); font-size:9.5px; letter-spacing:.02em } .ng-boxtext.ng-named { font-size:13px }
.ng-box { stroke-width:1.6 } .ng-boxtext { font-weight:600; font-size:11px } .ng-event .ng-boxtext { fill:#fcd34d; font-family:var(--mono); font-size:10px }
.ng-cloud { fill:none; stroke:var(--muted); stroke-width:1.2; opacity:.7 } .ng-edge.ng-outside .ng-line { opacity:.5 } .ng-edge.ng-outside .ng-flowdash { opacity:.4 } .ng-grab { fill:transparent; pointer-events:all } .ng-cloud:hover, .ng-node:hover .ng-cloud { stroke:var(--text) }
.ng-halo { fill:none; stroke:url(#ng-halo); stroke-width:4; stroke-dasharray:14 10; stroke-linecap:round; filter:drop-shadow(0 0 5px #60a5fa); animation:ng-halo 2.4s linear infinite; transform-box:fill-box; transform-origin:center }
@keyframes ng-halo { to { transform:rotate(360deg) } }
.ng-line { fill:none; opacity:.85 } .ng-gap { fill:none; stroke:var(--panel2); stroke-width:1.8; pointer-events:none } .ng-double .ng-line, .ng-double .ng-line.ng-hover, .ng-hl.ng-double .ng-line { stroke-width:5 } .ng-hit { fill:none; stroke:transparent; stroke-width:12; cursor:pointer }
.ng-flowdash { fill:none; stroke:#fff; stroke-width:2.2; stroke-dasharray:2 14; opacity:.7; pointer-events:none; animation:ng-flow linear infinite }
@keyframes ng-flow { to { stroke-dashoffset:-32 } }
.ng-elabel { fill:var(--text); font-size:10.5px; paint-order:stroke; stroke:var(--panel2); stroke-width:3px; pointer-events:none } .ng-elabel tspan + tspan { font-weight:600 }
.ng-sign { font-size:15px; font-weight:800; paint-order:stroke; stroke:var(--panel2); stroke-width:3px }
.ng-dim { opacity:.1; transition:opacity .15s } .ng-hl .ng-line { stroke:#fcd34d !important; stroke-width:2.6 } .ng-node.ng-hl .ng-box, .ng-node.ng-hl > circle:not(.ng-halo) { stroke:#fcd34d; stroke-width:3 }
.ng-tip { display:none; position:fixed; z-index:60; pointer-events:none; background:var(--panel2); border:1px solid var(--border2); border-radius:8px; padding:7px 10px; font-size:12px; box-shadow:0 8px 24px #0008; max-width:440px }
.ng-tip .tt { font-weight:700; margin-bottom:3px } .ng-tip .tr { display:flex; gap:14px; justify-content:space-between; white-space:nowrap } .ng-tip .tr b { font-family:var(--mono); font-weight:600 } .ng-tip .hint { color:var(--muted); font-size:10.5px; margin-top:4px }
.ng-loops { font-size:12px; color:var(--text2); margin-top:8px } .ng-loops .head { color:var(--muted); margin-bottom:4px }
.ng-loop { padding:4px 8px; border:1px solid var(--border); border-radius:8px; margin:4px 0; cursor:pointer; background:var(--panel) } .ng-loop:hover { border-color:var(--border2) }
.ng-loop.on { border-color:#fcd34d; background:#2a2208 } .ng-loop b { color:#fcd34d }
.ng-pol { display:inline-block; min-width:18px; text-align:center; font-weight:800; border-radius:4px; margin-right:6px; padding:0 4px }
.ng-pol.B { background:#1e3a5f; color:#93c5fd } .ng-pol.R { background:#4c1d1d; color:#fca5a5 }
.ng-frame { fill:rgba(148,163,184,.035); stroke:var(--muted); stroke-width:1.4; stroke-dasharray:9 6; pointer-events:none }
.ng-frame-label { fill:var(--muted); font-size:11px; letter-spacing:.06em; text-transform:uppercase; pointer-events:none }
.ng-fit { position:absolute; top:8px; right:8px; z-index:2 }
.ng-edge.ev-seen .ng-line { opacity:.85 } .ng-edge.ev-unseen .ng-line { opacity:.55 } .ng-edge .ng-line.ng-hover { stroke-width:2; opacity:1 }
.ng-pol.X { background:#1f2937; color:#cbd5e1 } .ng-pol.L { background:#3b2f0b; color:#fcd34d }
.ng-kind { display:inline-block; font-size:10.5px; border:1px solid var(--border2); border-radius:999px; padding:0 7px; margin-right:6px; color:var(--text2) } .ng-kind.mat { border-color:#14532d; color:#86efac }
.ng-edge.ev-handoff .ng-line { stroke-linecap:round }

/* a machine a package declared that has not been seen on the bus yet */
.panel.unseen { opacity:.62; border-style:dashed }

/* a machine's dialog (static/machine-dialog.js) */
.mdlg .seg { display:flex; gap:4px; flex-wrap:wrap; margin:4px 0 6px } .mdlg .seg button { background:var(--panel3); color:var(--text2); border:1px solid var(--border2); border-radius:6px; font:inherit; font-size:11.5px; padding:1px 8px; cursor:pointer } .mdlg .seg button.on { color:var(--text); border-color:var(--accent) }
.mdlg table.dt { width:100%; border-collapse:collapse; font-size:11.5px } .mdlg table.dt td, .mdlg table.dt th { padding:3px 6px; border-bottom:1px solid var(--border); text-align:left } .mdlg table.dt th { color:var(--muted); font-weight:600; font-size:10.5px; text-transform:uppercase }
.mdlg .num { font-family:var(--mono) } .mdlg h4 { margin:14px 0 6px; font-size:11px; text-transform:uppercase; letter-spacing:.05em; color:var(--muted) }
.tag.k-continuous { color:#93c5fd; border-color:#1d4ed8 } .tag.k-scheduled { color:#fcd34d; border-color:#92400e } .tag.k-ad_hoc { color:#c4b5fd; border-color:#5b21b6 }
.mdlg .row { font-size:12px; margin:4px 0; display:flex; gap:6px; flex-wrap:wrap; align-items:baseline } .mdlg .row > .muted:first-child { width:84px; flex:none }
.mdlg .ty { background:var(--panel3); border:1px solid var(--border); border-radius:999px; padding:0 8px; font-size:11px; font-family:var(--mono); max-width:100%; overflow-wrap:anywhere }
.mdlg h3 .tag { font-size:9.5px; font-weight:700; letter-spacing:.05em; text-transform:uppercase; color:#fde68a; border:1px solid #92400e; border-radius:4px; padding:0 4px; margin-left:4px }

