// Feedback loops, found the same way for the Dynamics graph and the Machines page's event map.
//
// A graph has many more elementary cycles than loops worth reading (the bakery's event map: 649).
// They are grouped and reduced by what can be shown, not by what looks alike:
//
// 1. feedback structures: the strongly connected parts of the graph (every node in one reaches
//    every other). Every cycle lies inside exactly one, and they are unique;
// 2. in each, an independent loop set: the shortest cycle through each link, taken shortest first
//    and kept only when it uses a link no loop kept before it uses (Oliva, "Model structure analysis
//    through graph theory", System Dynamics Review, 2004). Every other cycle is made of these
//    loops' links; there are at most links − nodes + 1 of them per structure;
// 3. cycles through exactly the same nodes are one loop with several routes;
// 4. two nodes that link both ways directly are an exchange (a request and its reply), listed
//    apart and not counted as loops; a loop is at least three nodes long.
//
// Edges are {source, target, sign?, kind?, via?}; ``sign`` (+1/−1) gives a loop's polarity
// (balancing when the product is negative), ``kind`` lets the caller say what each link is.
(function (root, factory) {
  if (typeof module === "object" && module.exports) module.exports = factory();
  else root.Loops = factory();
})(typeof self !== "undefined" ? self : this, function () {
  // strongly connected parts (Tarjan), as arrays of node ids
  function structures(nodeIds, edges) {
    const adj = new Map(nodeIds.map((id) => [id, []]));
    for (const e of edges) if (adj.has(e.source) && adj.has(e.target)) adj.get(e.source).push(e.target);
    let i = 0;
    const index = new Map(), low = new Map(), on = new Set(), stack = [], out = [];
    const visit = (v) => {                      // iterative, so deep graphs cannot overflow the stack
      const work = [[v, 0]];
      index.set(v, i); low.set(v, i); i++; stack.push(v); on.add(v);
      while (work.length) {
        const top = work[work.length - 1], [u, k] = top, next = adj.get(u);
        if (k < next.length) {
          top[1]++;
          const w = next[k];
          if (!index.has(w)) { index.set(w, i); low.set(w, i); i++; stack.push(w); on.add(w); work.push([w, 0]); }
          else if (on.has(w)) low.set(u, Math.min(low.get(u), index.get(w)));
        } else {
          work.pop();
          if (work.length) { const p = work[work.length - 1][0]; low.set(p, Math.min(low.get(p), low.get(u))); }
          if (low.get(u) === index.get(u)) {
            const part = [];
            let w;
            do { w = stack.pop(); on.delete(w); part.push(w); } while (w !== u);
            out.push(part);
          }
        }
      }
    };
    for (const v of nodeIds) if (!index.has(v)) visit(v);
    return out;
  }

  // the shortest path from a to b inside ``members`` (BFS), not using the link ``skip`` ("x>y")
  function shortestPath(adj, members, a, b, skip) {
    const prev = new Map([[a, null]]), queue = [a];
    while (queue.length) {
      const u = queue.shift();
      if (u === b) break;
      for (const w of adj.get(u) || []) {
        if (!members.has(w) || prev.has(w) || `${u}>${w}` === skip) continue;
        prev.set(w, u); queue.push(w);
      }
    }
    if (!prev.has(b)) return null;
    const path = [];
    for (let v = b; v !== null; v = prev.get(v)) path.unshift(v);
    return path;
  }

  // how many elementary cycles a part has, counted up to ``cap`` (for "and N more")
  function countCycles(members, adj, cap = 2000) {
    const ids = [...members], order = new Map(ids.map((id, k) => [id, k]));
    let n = 0;
    for (const start of ids) {
      const s = order.get(start), onPath = new Set([start]);
      const go = (v, depth) => {
        for (const w of adj.get(v) || []) {
          if (n >= cap) return;
          if (!members.has(w)) continue;
          if (w === start) { n++; continue; }
          if (order.get(w) < s || onPath.has(w) || depth > 24) continue;
          onPath.add(w); go(w, depth + 1); onPath.delete(w);
        }
      };
      go(start, 0);
      if (n >= cap) break;
    }
    return n;
  }

  // ``minLength``: the fewest nodes a loop may have (3 when two-way pairs are exchanges)
  function analyse(nodeIds, edges, { exchanges = false, minLength = exchanges ? 3 : 1 } = {}) {
    const adj = new Map(nodeIds.map((id) => [id, []])), link = new Map();
    for (const e of edges) {
      if (!adj.has(e.source) || !adj.has(e.target)) continue;
      const k = `${e.source}>${e.target}`;
      if (!link.has(k)) { adj.get(e.source).push(e.target); link.set(k, []); }
      link.get(k).push(e);
    }
    const pairs = [];
    if (exchanges) {
      for (const k of link.keys()) {
        const [a, b] = k.split(">");
        if (a < b && link.has(`${b}>${a}`)) pairs.push({ nodes: [a, b], there: link.get(k), back: link.get(`${b}>${a}`) });
      }
    }
    const out = { structures: [], exchanges: pairs };
    for (const part of structures(nodeIds, edges)) {
      const members = new Set(part);
      const inner = [...link.keys()].filter((k) => { const [a, b] = k.split(">"); return members.has(a) && members.has(b); });
      if (!inner.length) continue;
      // the shortest cycle through each link (of at least minLength nodes)
      const candidates = [];
      for (const k of inner) {
        const [u, v] = k.split(">");
        if (u === v) { if (minLength <= 1) candidates.push([u]); continue; }
        let path = shortestPath(adj, members, v, u, minLength > 2 ? `${v}>${u}` : null);
        if (!path) continue;
        if (path.length < minLength) {                           // too short: look for the shortest long enough
          path = null;
          for (const w of adj.get(v)) {
            if (w === u || !members.has(w)) continue;
            const p = shortestPath(adj, members, w, u, `${v}>${u}`);
            if (p && !p.includes(v) && p.length + 1 >= minLength && (!path || p.length + 1 < path.length)) path = [v, ...p];
          }
          if (!path) continue;
        }
        candidates.push([u, ...path.slice(0, -1)]);               // u → v → … → (back to u)
      }
      candidates.sort((a, b) => a.length - b.length);
      // keep a cycle when it uses a link no kept cycle uses; merge cycles through the same nodes
      const covered = new Set(), kept = [], bySet = new Map();
      for (const c0 of candidates) {
        const r0 = c0.indexOf([...c0].sort()[0]), c = [...c0.slice(r0), ...c0.slice(0, r0)];   // one rotation per cycle
        const ks = c.map((id, j) => `${id}>${c[(j + 1) % c.length]}`);
        const key = [...c].sort().join("|");
        if (bySet.has(key)) { const l = bySet.get(key); if (!l.routes.some((r) => r.join() === c.join())) l.routes.push(c); ks.forEach((x) => covered.add(x)); continue; }
        if (ks.every((x) => covered.has(x))) continue;
        ks.forEach((x) => covered.add(x));
        const loop = { nodes: c, links: ks.map((x) => link.get(x)), routes: [c] };
        const signs = loop.links.map((ls) => (ls[0].sign == null ? 1 : ls[0].sign));
        loop.negatives = signs.filter((s) => s < 0).length;
        loop.polarity = signs.some((s) => s === 0) ? "?" : loop.negatives % 2 ? "B" : "R";
        kept.push(loop); bySet.set(key, loop);
      }
      if (!kept.length) continue;
      const nodesIn = part.length, linksIn = inner.length;
      out.structures.push({ nodes: part, loops: kept, links: linksIn, independent: linksIn - nodesIn + 1, cycles: countCycles(members, adj) });
    }
    out.structures.sort((a, b) => b.nodes.length - a.nodes.length);
    return out;
  }

  return { analyse, structures };
});

/plugins/agents/static/ticket-sessions.j.body:
// The agents' sessions in the task system's ticket drawer (a plugin script, on every page). The
// task system's tasks.js announces each drawer it opens with "tasks:ticket-drawer" on document,
// detail {id, ticket, mount}: `mount` is an empty element in the drawer for other packages. This
// fills it with every agent turn that worked on the ticket (GET /sessions?ticket=: the worker's
// turns, each review round, and the Coordinator's, the Supervisor's or another agent's turns about
// it), each with its role, instance, when, outcome and last words, and its transcript a click
// away: inline, one turn read at a glance (agents.js renderTurn), or the whole session. While the
// drawer is open it follows the ticket every few seconds, so a running turn shows as it goes.
// The two packages import nothing of each other; without the task system this never runs.
(function () {
  const API = "/api/plugins/agents";
  const POLL_MS = 5000;
  const ROLE_C = { supervisor: "var(--r-supervisor)", coordinator: "var(--r-coordinator)", worker: "var(--r-worker)", reviewer: "var(--r-reviewer)" };
  const OUT_C = { APPROVED: "#22c55e", DONE: "#22c55e", READY_FOR_REVIEW: "#a78bfa", REJECTED: "#f87171", BLOCKED: "#fb923c", running: "#60a5fa",
                  "cut off": "#fbbf24", failed: "#f87171", interrupted: "#f87171", "no report": "#9ca3af", "no verdict": "#9ca3af" };
  const libs = () => (window.__agentsJs = window.__agentsJs || (typeof window.renderTurn === "function" ? Promise.resolve()
    : new Promise((ok) => { const s = document.createElement("script"); s.src = "/plugins/agents/static/agents.js"; s.onload = ok; s.onerror = ok; document.head.appendChild(s); })));
  let cur = null;   // {id, mount, sig, open: Set of "session:start", timer}

  const key = (t) => `${t.session}:${t.start}`;
  const clock = (t) => (t ? new Date(t * 1000).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" }) : "");
  const dur = (s) => (s == null ? "" : s >= 3600 ? `${Math.floor(s / 3600)}h ${Math.round((s % 3600) / 60)}m` : s >= 60 ? `${Math.floor(s / 60)}m ${Math.round(s % 60)}s` : `${Math.max(0, Math.round(s))}s`);

  // what a turn was, in a few words: a worker's turn, a review round, or another agent's turn about the ticket
  function what(t, rounds) {
    if (t.own && t.role === "reviewer") return `review round ${rounds[key(t)]}`;
    if (t.own && t.kind === "assignment") return `turn ${rounds[key(t)]}`;
    if (t.own) return t.session.includes("-verdict-") ? "prediction verdict" : t.kind;
    const why = t.kind === "wake" ? "woken" : t.kind === "chat" ? "chat with you" : t.kind;
    return `${why}${t.touched.length ? " · " + t.touched.join(", ") : " · mentions it"}`;
  }

  function row(t, now, rounds) {
    const ended = t.running ? `running ${dur(now - t.started)}` : `${clock(t.started)}${t.ended && t.started ? ` · ${dur(t.ended - t.started)}` : ""}`;
    const open = cur.open.has(key(t));
    const say = (t.reply || "").replace(/\s+/g, " ").trim();
    return `<div class="tks-row" style="--rc:${ROLE_C[t.role] || "#c4b5fd"}" data-k="${esc(key(t))}">
      <div class="tks-top"><span class="who">${esc(t.instance || t.role)}</span><span class="what">${esc(what(t, rounds))}</span>
        <span class="when" title="${t.started ? esc(new Date(t.started * 1000).toLocaleString()) : ""}">${esc(ended)}${t.archived ? ' <span class="muted">· session archived</span>' : ""}</span>
        <span class="out ${t.running ? "running" : ""}" style="--oc:${OUT_C[t.outcome] || "#9ca3af"}">${esc(String(t.outcome).replace(/_/g, " "))}</span>
        <span class="acts"><button onclick="TicketSessions.toggle('${esc(key(t))}')">${open ? "hide" : "transcript"}</button><button title="the whole session (every turn); its ticket link comes back here" onclick="TicketSessions.session('${esc(t.session)}')">session ↗</button></span></div>
      ${say ? `<div class="say" title="${esc(say.slice(0, 600))}">${esc(say.slice(0, 240))}</div>` : ""}
      ${open ? `<div class="tks-turn" id="tks-${esc(key(t))}"><div class="empty">loading…</div></div>` : ""}</div>`;
  }

  async function load() {
    const c = cur;
    if (!c) return;
    if (!document.body.contains(c.mount)) { stop(); return; }
    let d;
    try { d = await (await fetch(`${API}/sessions?ticket=${encodeURIComponent(c.id)}`)).json(); } catch (e) { return; }
    if (cur !== c || !d.ok) return;
    c.turns = d.turns;
    const sig = JSON.stringify([d.turns.map((t) => [key(t), t.outcome, t.end, t.reply.length, t.running]), [...c.open]]);
    const running = d.turns.some((t) => t.running);
    if (sig === c.sig && !running) return;
    const first = c.sig === undefined;
    c.sig = sig;
    const rounds = {}, n = {};
    d.turns.filter((t) => t.own).forEach((t) => { n[t.session] = (n[t.session] || 0) + 1; rounds[key(t)] = n[t.session]; });
    const live = d.turns.filter((t) => t.running).length;
    c.mount.innerHTML = `<div class="tks"><div class="tks-head"><h2 style="margin:0">Agent sessions</h2><span class="muted">${d.turns.length
      ? `${d.turns.length} turn${d.turns.length === 1 ? "" : "s"}${live ? ` · ${live} running, following it live` : ""}` : ""}</span></div>
      ${d.turns.map((t) => row(t, d.now, rounds)).join("") || `<div class="empty">No agent has worked on this ticket${first ? "" : " yet"}. A program may have (the Machines page shows who took it).</div>`}</div>`;
    for (const k of c.open) fill(k);
  }

  async function fill(k) {
    const c = cur, t = c && (c.turns || []).find((x) => key(x) === k);
    const box = document.getElementById(`tks-${k}`);
    if (!t || !box) return;
    const q = t.running ? `start=${t.start}` : `start=${t.start}&end=${t.end}`;
    try {
      const d = await (await fetch(`${API}/sessions/${encodeURIComponent(t.session)}/messages?${q}`)).json();
      if (!document.getElementById(`tks-${k}`)) return;
      const opened = [...box.querySelectorAll("details[open]")].map((x) => x.querySelector("summary").textContent);
      box.innerHTML = renderTurn(d.messages || [], d.markers || []);
      box.querySelectorAll("details").forEach((x) => { if (opened.includes(x.querySelector("summary").textContent)) x.open = true; });
      if (typeof highlightCode === "function") highlightCode(box);
    } catch (e) { box.innerHTML = `<div class="bad">${esc(String(e))}</div>`; }
  }

  function stop() { if (cur) clearInterval(cur.timer); cur = null; }

  window.TicketSessions = {
    toggle(k) { if (!cur) return; cur.open.has(k) ? cur.open.delete(k) : cur.open.add(k); cur.sig = null; load(); },
    session(sid) { openTranscript(sid); },
  };

  document.addEventListener("tasks:ticket-drawer", async (e) => {
    const { id, mount } = e.detail || {};
    if (!id || !mount) return;
    stop();
    cur = { id, mount, open: new Set(), sig: undefined };
    mount.innerHTML = '<div class="tks"><h2>Agent sessions</h2><div class="empty">loading…</div></div>';
    await libs();
    if (!cur || cur.mount !== mount) return;
    cur.timer = setInterval(load, POLL_MS);
    load();
  });
})();

/plugins/agents/static/attention.js.body:
// What waits on the human, on every page of Orchestra's web UI (a plugin script: Orchestra loads it
// and knows nothing of it). Blocked tickets and Supervisor messages not yet read become:
// - a "Supervisor" button in the navigation, with a count when something waits;
// - a banner under the navigation that says what waits, with a way to answer;
// - "(n)" in the tab's title.
// The button opens the Supervisor's chat (agents.js) with the list of what waits above it, and the
// message it announced marked in the transcript (or, when the transcript does not hold it, shown
// in full above it). A message is only what the Supervisor wrote for the human (the agents'
// attention.py: a reply to the human, or a wake-up's reply that says something); one that arrives
// while the chat is open in front of the human is read there and announces nothing. The
// Supervisor is the human's one way in: blocked work is answered by telling it what to do. The
// task system's own banner (its attention.js) shows the same blocked tickets; it is asked to stand
// aside once it is on the page, so there is one banner.
(function () {
  const API = "/api/plugins/agents", TASKS = "/api/plugins/tasks";      // blocked tickets: the task system's, when it is installed
  const POLL_MS = 5000;
  const load = (src) => new Promise((ok, bad) => { const s = document.createElement("script"); s.src = src; s.onload = ok; s.onerror = bad; document.head.appendChild(s); });

  // what the chat drawer needs: agents.js (transcripts, the chat, markdown rendering); the agents'
  // look, agents.css, is a stylesheet the plugin declares, linked by Orchestra in every page's head
  async function ready() {
    window.__agentsJs = window.__agentsJs || (typeof window.openTranscript === "function" ? Promise.resolve() : load("/plugins/agents/static/agents.js").catch(() => {}));
    await window.__agentsJs;                         // loaded once, whichever of the agents' scripts asks first
    if (typeof agentsLibs !== "undefined") await agentsLibs;   // agents.js's markdown libraries
  }

  const css = document.createElement("style");
  css.textContent = `
    .att-btn { display:inline-flex; align-items:center; gap:6px; margin-left:14px; padding:3px 10px; border-radius:999px;
      border:1px solid var(--border2, #2a3142); background:transparent; color:var(--text, #e6e8ee); font:inherit; font-size:12px; cursor:pointer }
    .att-btn:hover { border-color:#6ea8fe }
    .att-btn .att-n { min-width:18px; height:18px; padding:0 5px; border-radius:9px; background:#f59e0b; color:#1a1205;
      font-weight:700; font-size:11px; display:none; align-items:center; justify-content:center }
    .att-btn.on { border-color:#f59e0b; box-shadow:0 0 0 0 rgba(245,158,11,.6); animation:att-pulse 2s infinite }
    .att-btn.count .att-n { display:inline-flex }
    .att-btn .att-dot { width:7px; height:7px; border-radius:50%; background:#6ea8fe; display:none }
    .att-btn.working .att-dot { display:inline-block; animation:att-blink 1s infinite alternate }
    @keyframes att-pulse { 0% { box-shadow:0 0 0 0 rgba(245,158,11,.55) } 70% { box-shadow:0 0 0 8px rgba(245,158,11,0) } 100% { box-shadow:0 0 0 0 rgba(245,158,11,0) } }
    @keyframes att-blink { from { opacity:.25 } to { opacity:1 } }
    .att-bar { display:none; align-items:center; gap:12px; padding:8px 16px; background:linear-gradient(90deg, rgba(245,158,11,.16), rgba(245,158,11,.05));
      border-bottom:1px solid rgba(245,158,11,.45); color:var(--text, #e6e8ee); font-size:13px }
    .att-bar.on { display:flex }
    .att-bar b { color:#fbbf24 }
    .att-bar .att-what { flex:1; min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap }
    .att-bar button { flex:none; padding:4px 12px; border-radius:6px; border:1px solid #f59e0b; background:#f59e0b; color:#1a1205; font-weight:600; cursor:pointer }
    .att-bar .att-x { background:transparent; border-color:transparent; color:var(--muted, #8a90a3); font-weight:400; padding:4px 6px }
    .att-bar button.att-down, .att-item button.att-down { background:transparent; border-color:var(--border2, #2a3142); color:var(--muted, #8a90a3); font-weight:400 }
    .att-panel { border:1px solid rgba(245,158,11,.5); background:rgba(245,158,11,.07); border-radius:8px; padding:12px 14px; margin:4px 0 14px }
    .att-panel h4 { margin:0 0 8px; color:#fbbf24; font-size:12px; letter-spacing:.06em; text-transform:uppercase }
    .att-item { display:grid; grid-template-columns:1fr auto; gap:4px 12px; padding:8px 0; border-top:1px solid rgba(245,158,11,.2) }
    .att-item:first-of-type { border-top:none }
    .att-item .att-t { font-weight:600 } .att-item .att-t code { color:#fbbf24 }
    .att-item .att-r { grid-column:1; color:var(--muted, #8a90a3); font-size:12px; line-height:1.45; max-height:5.8em; overflow:hidden }
    .att-item .att-acts { grid-column:2; grid-row:1 / span 2; display:flex; flex-direction:column; gap:6px; align-items:stretch }
    .att-item button { padding:3px 10px; border-radius:6px; border:1px solid var(--border2, #2a3142); background:var(--panel2, #151a24); color:var(--text, #e6e8ee); cursor:pointer; font-size:12px }
    .att-item button.primary { border-color:#f59e0b; color:#fbbf24 }
    .att-item .att-full { grid-column:1; font-size:13px } .att-item .att-r a { color:#fbbf24 }
    #transcript .msg.for-you { border-left-color:#f59e0b; background:rgba(245,158,11,.07) }
    #transcript .msg.for-you > .r::after { content:" · for you"; color:#fbbf24; font-weight:600 }
    @media (max-width:640px) {
      .att-bar .att-what { white-space:normal } .att-item { grid-template-columns:1fr } .att-item .att-acts { grid-column:1; grid-row:auto; flex-direction:row }
      /* the navigation is one line that does not wrap: the button shrinks to its icon and count and goes first, the project name goes, and the line scrolls sideways */
      .att-btn { order:-1; margin:0 6px 0 0; padding:3px 7px } .att-btn .att-word { display:none } nav #proj { display:none }
      #nav { overflow-x:auto; scrollbar-width:none } #nav::-webkit-scrollbar { display:none } }`;
  document.head.appendChild(css);

  let A = { blocked: [], message: null, count: 0, working: false, host: { alive: true } };   // blocked: the task system's [{id, reason}]
  let shown = null;                         // the message the open chat was opened for: its panel item stays while the chat is open
  let dismissed = "";                       // the banner's content when the viewer closed it
  let rendered = "";                        // the banner's content as last built: a click never lands on a replaced button
  const baseTitle = document.title;
  const hostUp = () => !A.host || A.host.alive !== false;
  const sig = () => JSON.stringify([A.blocked.map((b) => b.id), A.message && A.message.at, hostUp()]);
  const ago_ = (t) => (typeof ago === "function" && t ? ago(Date.now() / 1000 - t) : "");
  const e_ = (s) => (typeof esc === "function" ? esc(s) : String(s ?? ""));
  // With the host down nothing can be answered: the way in still opens the chat, which says so, but does not promise an answer.
  const DOWN = "the Supervisor is down · start orchestra run";
  const answerBtn = (onclick, label) => (hostUp() ? `<button class="primary" onclick="${onclick}">${label}</button>`
    : `<button class="att-down" onclick="window.SupervisorAttention.open()">${DOWN}</button>`);

  // the navigation button
  const btn = document.createElement("button");
  btn.className = "att-btn"; btn.type = "button";
  btn.innerHTML = '<span>💬<span class="att-word"> Supervisor</span></span><span class="att-dot" title="the Supervisor is working"></span><span class="att-n"></span>';
  btn.onclick = () => openSupervisor();
  const nav = document.getElementById("nav");
  if (nav) nav.insertBefore(btn, document.getElementById("proj"));

  // the banner, right under the navigation
  const bar = document.createElement("div");
  bar.className = "att-bar";
  if (nav) nav.insertAdjacentElement("afterend", bar);

  function render() {
    btn.classList.toggle("count", A.count > 0);
    btn.classList.toggle("on", A.count > 0 && hostUp());        // the pulse asks for an answer; with the host down there is none to give
    btn.classList.toggle("working", !!A.working && hostUp());
    btn.querySelector(".att-n").textContent = A.count || "";
    btn.title = A.count ? `${A.count} thing${A.count === 1 ? "" : "s"} waiting on you${hostUp() ? "" : " (" + DOWN + ")"}` : hostUp() ? "Talk to the Supervisor" : DOWN;
    document.title = (A.count ? `(${A.count}) ` : "") + baseTitle;
    const parts = [];
    if (A.blocked.length) parts.push(`<b>${A.blocked.length} ticket${A.blocked.length === 1 ? " is" : "s are"} blocked</b> waiting for a decision (${A.blocked.slice(0, 3).map((b) => e_(b.id)).join(", ")}${A.blocked.length > 3 ? ", …" : ""})`);
    if (A.message && A.message.kind === "failed") parts.push(`<b>the Supervisor's turn failed</b> ${ago_(A.message.at)} ago: ${e_((A.message.text.split("\n\n")[1] || "").slice(0, 160))}`);
    else if (A.message) parts.push(`<b>the Supervisor wrote to you</b>${A.message.count > 1 ? ` (${A.message.count} messages)` : ""} ${ago_(A.message.at)} ago`);
    const show = parts.length && sig() !== dismissed;
    bar.classList.toggle("on", !!show);
    if (show && sig() !== rendered) {
      rendered = sig();
      bar.innerHTML = `<span>⚠</span><span class="att-what">${parts.join(" · ")}</span>
      <button class="${hostUp() ? "" : "att-down"}" onclick="window.SupervisorAttention.open()">${hostUp() ? "Review &amp; answer" : DOWN}</button><button class="att-x" title="hide until something changes" onclick="window.SupervisorAttention.dismiss()">✕</button>`;
    }
    const panel = document.getElementById("att-panel");
    if (panel) panel.outerHTML = panelHtml();
  }

  function panelHtml() {
    const msg = shown || A.message;
    if (!A.blocked.length && !msg) return '<div id="att-panel"></div>';
    const items = A.blocked.map((b) => `<div class="att-item">
        <div class="att-t"><code>${e_(b.id)}</code> <span class="muted" style="font-weight:400">· blocked</span></div>
        <div class="att-r">${e_(b.reason) || "(no reason recorded)"}</div>
        <div class="att-acts">${answerBtn(`window.SupervisorAttention.answer('${e_(b.id)}')`, "Answer")}
          <button onclick="window.openTicket ? openTicket('${e_(b.id)}') : (location.href='/tickets#ticket=${e_(b.id)}')">Ticket</button></div></div>`);
    if (msg) {
      const woke = msg.woken_by && msg.woken_by.length ? `<div class="att-r">An event woke it, not you: ${e_(msg.woken_by[0].slice(0, 240))}${msg.woken_by[0].length > 240 ? "…" : ""}</div>` : "";
      const failed = msg.kind === "failed";
      const where = msg.in_chat === false ? `<div class="att-full">${typeof md === "function" ? md(msg.text) : e_(msg.text)}</div>
          <div class="att-r">${failed ? "Orchestra wrote this, not the Supervisor: the turn did not run." : "Its transcript does not hold this message (the turn was cut off, or the transcript moved on), so it is shown here."}</div>`
        : `<div class="att-r">${e_(msg.text.slice(0, 300))}${msg.text.length > 300 ? "…" : ""}</div>
           <div class="att-r"><a href="#" onclick="window.SupervisorAttention.show();return false">marked in the transcript below ↓</a></div>`;
      items.unshift(`<div class="att-item">
        <div class="att-t">${failed ? "The Supervisor's turn failed" : "The Supervisor wrote to you"} <span class="muted" style="font-weight:400">· ${ago_(msg.at)} ago${msg.count > 1 ? ` · ${msg.count} messages since you last looked` : ""}</span></div>
        ${woke}${where}
        <div class="att-acts">${answerBtn("document.getElementById('chat-input')?.focus()", "Reply")}</div></div>`);
    }
    return `<div id="att-panel" class="att-panel"><h4>Waiting on you</h4>${items.join("")}
      ${A.blocked.length ? '<div class="muted" style="font-size:11px;margin-top:6px">Answer by telling the Supervisor what to do; it unblocks, changes or cancels the ticket.</div>' : ""}</div>`;
  }

  async function refresh() {
    try {
      const d = await (await fetch(API + "/attention")).json();
      const t = await fetch(TASKS + "/attention").then((r) => (r.ok ? r.json() : {})).catch(() => ({}));
      d.blocked = t.blocked || [];
      // the chat is open in front of the human: what the Supervisor writes there now is read there
      if (d.message && chatOpen()) { const m = d.message; await markSeen(); d.message = null; setTimeout(() => mark(m), POLL_MS + 500); }
      d.count = (d.message ? 1 : 0) + d.blocked.length;
      if (d.ok) { A = d; render(); }
    } catch (e) { /* the task system is down: keep the last state */ }
  }

  async function markSeen() {
    try { await fetch(API + "/attention/seen", { method: "POST" }); } catch (e) {}
  }
  const chatOpen = () => document.visibilityState === "visible" && !!document.getElementById("chat")
    && !!(document.getElementById("overlay") || {}).classList?.contains("open");
  // the announced message, in the open transcript: marked "for you" and brought into view
  function mark(m, scroll) {
    if (!m || m.index == null) return false;
    const el = document.querySelector(`#transcript [data-i="${m.index}"]`);
    if (!el) return false;
    el.classList.add("for-you");
    if (scroll) el.scrollIntoView({ block: "center" });
    return true;
  }

  // the Supervisor's chat, with what waits listed above the message box
  async function openSupervisor(prefill) {
    if (typeof window.openDrawer === "function") openDrawer('<h3>Supervisor</h3><div class="empty">opening the Supervisor…</div>');   // the scripts take a moment
    await ready();
    await openTranscript("supervisor");
    const chat = document.getElementById("chat"), head = document.getElementById("transcript-head");
    if (!document.getElementById("att-panel")) {
      if (chat) chat.insertAdjacentHTML("beforebegin", panelHtml());
      else if (head) head.insertAdjacentHTML("afterend", panelHtml());
    }
    if (prefill) {
      const ta = document.getElementById("chat-input");
      if (ta && !ta.disabled) { ta.value = prefill; ta.focus(); ta.setSelectionRange(ta.value.length, ta.value.length); }
    }
    // reading the chat reads the message; blocked tickets stay until they are unblocked
    shown = A.message;
    const panel = document.getElementById("att-panel"); if (panel) panel.outerHTML = panelHtml();
    if (A.message) { mark(A.message); await markSeen(); A.message = null; A.count = A.blocked.length; render(); }
  }

  // after the human writes, the Supervisor's reply arrives in the open chat: it is read
  const wrapSend = () => {
    if (typeof window.sendToSupervisor !== "function" || window.sendToSupervisor.__att) return;
    const orig = window.sendToSupervisor;
    window.sendToSupervisor = async function (ev) { const r = await orig(ev); await markSeen(); refresh(); return r; };
    window.sendToSupervisor.__att = true;
  };

  window.SupervisorAttention = {
    open: () => openSupervisor(),
    show: () => mark(shown, true),
    dismiss: () => { dismissed = sig(); render(); },
    answer: (id) => openSupervisor(`About ${id}, which is blocked: `),
  };

  const aside = () => { const t = window.TaskAttention; if (!t || !t.standAside) return false; t.standAside(); return true; };
  if (!aside()) { const t = setInterval(() => { if (aside()) clearInterval(t); }, 500); setTimeout(() => clearInterval(t), 30000); }

  refresh();
  setInterval(() => { wrapSend(); refresh(); }, POLL_MS);
  setTimeout(wrapSend, 500);
})();

/plugins/agents/static/machine-cards.js.body:
// The agents on Orchestra's pages (a plugin script; Orchestra.machineCards in Orchestra's
// app.js), inside Orchestra's machine-card frame:
// - a resident agent (the Supervisor, the Coordinator) is a row: its letter in its role's colour,
//   what it last said, and its session chip (resident, working, waiting);
// - workers and reviewers are the tickets they were assigned: a card per ticket an instance is on,
//   in the ticket's state colour, with its id, title, re-engagement badge and state, and a lane
//   with what the agent is saying now.
// The agents' host is no machine (it never announces itself or publishes as itself), so it has no
// card; whether it is up is on the Agents page and on each agent's session chip.
// A click opens the agent's transcript (the ticket id opens the ticket, when a task system with a
// ticket view is loaded); "machine details", on the Machines page, opens Orchestra's own view.
// Under the live cards, "finished sessions" lists the role's recent sessions that are over, whose
// instance has moved on, each a click from its transcript.
(async function () {
  if (!window.Orchestra || !Orchestra.machineCards) return;
  const API = "/api/plugins/agents";
  window.__agentsJs = window.__agentsJs || (typeof window.sessionChip === "function" ? Promise.resolve()   // transcripts, chat, chips
    : new Promise((ok) => { const s = document.createElement("script"); s.src = "/plugins/agents/static/agents.js"; s.onload = ok; s.onerror = ok; document.head.appendChild(s); }));
  await window.__agentsJs;
  let D = null, last = "";
  const e_ = (s) => esc(s);
  const ROLE_C = { supervisor: "var(--r-supervisor)", coordinator: "var(--r-coordinator)", worker: "var(--r-worker)", reviewer: "var(--r-reviewer)" };
  const RANK = { supervisor: 10, coordinator: 11, worker: 30, reviewer: 31 };
  const stateColor = (st) => (typeof color === "function" ? color(st) : "var(--muted)");
  const kindOf = (m) => (m.kinds && m.kinds.agent ? "agent" : m.kind);   // a machine with any agent instance is an agent here (worker: agent ×2, program ×1)
  const roleOf = (m) => (m.about && m.about.role) || m.id;
  const sessionsOf = (m) => (D ? D.sessions.filter((s) => s.role === roleOf(m)) : []);
  // what is known of the agent beyond its sessions, for its status (agents.js agentStatus)
  const agentOf = (m) => { const a = D && D.agents.find((x) => x.name === roleOf(m)); return a ? { ...a, host_alive: D.host.alive } : { host_alive: D ? D.host.alive : undefined }; };
  // a per-ticket role's machine shows the tickets it is on, even when a program fills the role beside the agents (its mode is then mixed)
  const perTicket = (m) => { const a = D && D.agents.find((x) => x.name === roleOf(m)); return a ? !a.resident : m.mode === "ad hoc"; };
  const chip = (s, m) => (typeof sessionChip === "function" ? sessionChip(s, D ? D.now : Date.now() / 1000, m ? agentOf(m) : undefined) : "");
  const more = (m, compact) => (compact ? "" : `<div class="tkc-more" onclick="event.stopPropagation();Orchestra.machineCards.openDefault('${e_(m.id)}')">machine details</div>`);

  const css = document.createElement("style");
  css.textContent = `
    .tkc-more { text-align:right; font-size:10.5px; color:var(--muted); text-decoration:underline dotted; cursor:pointer; margin:6px 2px 0 }
    .agent.unseen-agent { opacity:.6; border-style:dashed }`;
  document.head.appendChild(css);

  // how many times a worker has taken the ticket (the assignment's brief says; the ticket says why)
  function turns(t) {
    if (!t || !t.worker_turns || t.worker_turns < 2) return "";
    return `<span class="turns" title="a worker took this ticket ${t.worker_turns} times; the ticket says why">↺${t.worker_turns}</span>`;
  }
  function residentCard(m, compact) {
    const s = sessionsOf(m).sort((a, b) => (b.started_at || 0) - (a.started_at || 0))[0];
    // the stored text is a message's tail, markdown and all: drop fence lines, emphasis markers and
    // backticks (the words stay), then start it at a sentence, not mid-word
    const tail = (s ? s.last_text || "" : "").replace(/^\s*```.*$/gm, "").replace(/\*\*|__|`|(^|\s)[*_](?=\S)|(?<=\S)[*_](?=\s|$)/g, "$1").trim(), cut = tail.search(/[.!?]\s+[A-Z(]/);
    const role = roleOf(m), say = tail.length >= 290 && cut >= 0 && cut < 160 ? tail.slice(cut + 1).trim() : tail;
    const a = agentOf(m), next = a.next_scheduled_at && !(s && s.status === "running") ? `next wake-up in ${ago(a.next_scheduled_at - D.now)}` : "";
    // with nothing said yet the status line already names the next wake-up
    const text = m.unseen ? "declared, not run yet" : say ? [say, next].filter(Boolean).join(" · ") : typeof agentStatus === "function" ? agentStatus(s, D.now, a).title : "";
    return `<div class="agent ${m.unseen ? "unseen-agent" : ""}" style="--rc:${ROLE_C[role] || "#c4b5fd"}" title="${e_(agentOf(m).description || role)}">
        <div class="av">${e_(m.id[0].toUpperCase())}</div><div class="name">${e_(m.id)}</div><div class="say">${e_(text)}</div>${s ? chip(s, m) : ""}</div>${more(m, compact)}`;
  }

  function ticketsCard(m, compact) {
    const role = roleOf(m), live = sessionsOf(m).filter((s) => s.status === "running");
    const cards = live.map((s) => {
      const t = s.ticket || { id: s.session, title: "", state: "IN_PROGRESS" };
      return `<div class="awork" style="--c:${stateColor(t.state)}" onclick="event.stopPropagation();AgentCards.transcript('${e_(s.session)}')" title="Open the running agent's transcript; the ticket id opens the ticket">
        <div class="top"><span><span class="id" onclick="event.stopPropagation();AgentCards.ticket('${e_(t.id)}')" title="Open the ticket">${e_(t.id)}</span> <span class="title">${e_(t.title)}</span></span>
        <span class="right">${turns(t)}<span class="pill">${e_(t.state.replace(/_/g, " "))}</span></span></div>
        <div class="lane"><span class="who">${e_(s.instance || role)}</span><span class="msg">${e_(s.last_text || "")}</span>${chip(s)}</div></div>`;
    }).join("");
    const empty = m.unseen ? `<div class="empty">Declared, not run yet: ${e_(role)}s start when a ticket is ready${role === "reviewer" ? " for review" : ""}.</div>`
      : `<div class="empty">No ${e_(role)} is on a ticket right now.${role === "worker" ? " Ready tickets start as soon as a worker slot is free." : ""}</div>`;
    return `<h2><span>${e_(m.id)} <span class="muted">· on tickets</span></span><span class="hctl"><span class="count">${live.length}</span></span></h2>${cards || empty}${compact ? "" : past(role)}${more(m, compact)}`;
  }

  // the sessions this role finished, newest first: an instance moves on to its next ticket (or is
  // gone), and its transcript stays a click away here and in the ticket's drawer
  function past(role) {
    const done = ((D && D.recent) || []).filter((x) => x.role === role);
    if (!done.length) return "";
    return `<details class="tkc-past" onclick="event.stopPropagation()"><summary>finished sessions (${done.length})</summary>${done.map((x) => `
      <div class="row" onclick="event.stopPropagation();AgentCards.transcript('${e_(x.session)}')" title="Open this session's transcript">
        <span class="id" onclick="event.stopPropagation();AgentCards.ticket('${e_(x.ticket)}')" title="Open the ticket">${e_(x.ticket)}</span>
        <span class="muted">${e_(x.instance)}</span><span>${e_(x.title || (x.last_text || "").replace(/\s+/g, " "))}</span>
        <span class="muted">${x.settled_at ? ago(D.now - x.settled_at) + " ago" : ""}</span></div>`).join("")}</details>`;
  }

  window.AgentCards = {
    transcript: (sid) => openTranscript(sid),
    ticket: (id) => (typeof window.openTicket === "function" ? window.openTicket(id) : null),
  };

  Orchestra.machineCards.register("agents", {
    rank: (m) => RANK[roleOf(m)] ?? (kindOf(m) === "agent" ? 12 : 25),
    // a few words for the Dashboard's machine list: what the machine is on now
    summary(m) {
      if (kindOf(m) !== "agent") return null;
      const live = sessionsOf(m).filter((s) => s.status === "running");
      if (live.length) return live.map((s) => `${e_(s.instance || roleOf(m))} on ${e_((s.ticket || {}).id || "a turn")}`).join(" · ") + " " + chip(live[0], m);
      const s = sessionsOf(m).sort((a, b) => (b.settled_at || 0) - (a.settled_at || 0))[0];
      return s || m.mode === "ad hoc" ? chip(s || null, m) : null;
    },
    card(m, { compact } = {}) {
      if (kindOf(m) !== "agent") return null;
      return perTicket(m) ? ticketsCard(m, compact) : residentCard(m, compact);
    },
    open(m) {
      if (kindOf(m) !== "agent" || m.unseen) return false;
      const s = sessionsOf(m).filter((x) => x.status === "running")[0] || sessionsOf(m).sort((a, b) => (b.started_at || 0) - (a.started_at || 0))[0];
      if (!s) return false;
      openTranscript(s.session);
      return true;
    },
  });

  async function refresh(force) {
    try {
      const d = await (await fetch(API + "/agents")).json();
      if (!d.ok) return;
      const sig = JSON.stringify([d.sessions.map((s) => [s.session, s.status, s.phase, s.last_text, s.tool_name]), (d.recent || []).map((x) => x.session), d.host.alive]);
      D = d;
      if (force || sig !== last) { last = sig; Orchestra.machineCards.changed(); }
    } catch (e) {}
  }
  refresh(true); setInterval(refresh, 3000);
})();

/plugins/tasks/static/tasks-boot.js.body:
// The task system's one every-page script (Orchestra loads it on every page of its web UI,
// orchestra/plugins.py): it loads tasks.js, the shared code and look, and then the scripts that
// need it: the blocked-ticket banner and the Tasks panel. A page
// that already has tasks.js (the Tickets page) keeps its copy; nothing is loaded twice.
(function () {
  const have = (path) => [...document.scripts].some((s) => s.src && new URL(s.src).pathname === path);
  const load = (name) => new Promise((ok) => {
    const path = `/plugins/tasks/static/${name}`;
    if (have(path)) return ok();
    const s = document.createElement("script"); s.src = path; s.onload = ok; s.onerror = ok; document.body.appendChild(s);
  });
  load("tasks.js").then(() => ["attention.js", "tasks-panel.js"].forEach(load));
})();

/plugins/tasks/static/tasks.js.body:
// The task system's shared page code: the ticket drawer (and its extension point,
// "tasks:ticket-drawer"), priorities, worker turns, the operator's controls. Loaded after Orchestra's /static/app.js (esc, color, openDrawer are its), by the
// Tickets page and by tasks-boot.js on every other page. The look every page needs (tasks.css: the
// ticket states, the Tasks panel's cards, the drawer) is a stylesheet the plugin declares, which
// Orchestra links in every page's head.
const TASKS_API = "/api/plugins/tasks";

// A ticket's text is markdown, written by whoever made the ticket: rendered and then sanitised
// (marked, DOMPurify, loaded once from cdnjs unless the page has them), and shown as escaped text
// until both have arrived.
for (const [lib, path] of [["marked", "marked/12.0.2/marked.min.js"], ["DOMPurify", "dompurify/3.1.6/purify.min.js"]]) {
  if (window[lib] || document.querySelector(`script[src$="${path}"]`)) continue;
  const s = document.createElement("script"); s.src = `https://cdnjs.cloudflare.com/ajax/libs/${path}`; document.head.appendChild(s);
}
function tasksMd(text) {
  if (!text) return "";
  if (!(window.marked && window.DOMPurify)) return `<pre>${esc(text)}</pre>`;
  return `<div class="md">${DOMPurify.sanitize(marked.parse(text, { gfm: true, breaks: true }))}</div>`;
}

// Worker turns: how many times a worker took the ticket, and why it took it again.
function turnsWhy(t) {
  const why = [];
  if (t.reviewer_rejections) why.push(`${t.reviewer_rejections} after a reviewer rejection`);
  if (t.gate_rejections) why.push(`${t.gate_rejections} after the merge gate sent it back`);
  if (t.pull_rejections) why.push(`${t.pull_rejections} after feedback on its pull request`);
  const other = (t.worker_turns || 0) - 1 - (t.reviewer_rejections || 0) - (t.gate_rejections || 0) - (t.pull_rejections || 0);
  if (other > 0) why.push(`${other} after a crash, timeout or operator stop`);
  return why;
}
function turnsText(t) {
  const n = t.worker_turns || 0;
  if (n < 2) return n === 1 ? "1 (first attempt)" : "none yet";
  return `${n} (${turnsWhy(t).join(", ")})`;
}

// The headline over the tickets, from a /board answer D: a partition of the tickets (every
// ticket in exactly one bucket, so the numbers add up to the ticket count), drawn by the Tasks
// panel. Zero buckets are left out except the two always shown; the
// finished ones (done, cancelled) are left out when finished is false.
function taskSummary(D, { finished = true } = {}) {
  const c = D.counts || {}, n = (s) => c[s] || 0;
  const offers = D.tickets.filter((t) => t.assignment && !t.assignment.instance);
  const resting = D.tickets.filter((t) => t.untaken && !t.assignment);     // offered, not taken: the next offer waits
  const of = (list, role) => list.filter((t) => (t.assignment || t.untaken).role === role).length;
  const k = {
    working: D.tickets.filter((t) => t.assignment && t.assignment.instance).length,
    offered: offers.length,
    preparing: D.tickets.filter((t) => t.preparing).length,
    untaken: resting.length,
    blocked: n("BLOCKED"),
    start: n("OPEN") + n("REJECTED") - of(offers, "worker") - of(resting, "worker"),
    review: n("READY_FOR_REVIEW") - of(offers, "reviewer") - of(resting, "reviewer")
      - D.tickets.filter((t) => t.preparing && t.preparing.role === "reviewer").length,
    landing: n("APPROVED") + n("MERGING"),
    external: n("IN_EXTERNAL_REVIEW"),
    done: n("DONE"), cancelled: n("CANCELLED") };
  const parts = [`${k.working} being worked`];
  if (k.offered) parts.push(`${k.offered} offered`);
  if (k.preparing) parts.push(`${k.preparing} preparing a worktree`);
  if (k.untaken) parts.push(`${k.untaken} offered, not taken`);
  if (k.blocked) parts.push(`${k.blocked} blocked`);
  parts.push(`${k.start} waiting to start`);
  if (k.review) parts.push(`${k.review} waiting for review`);
  if (k.landing) parts.push(`${k.landing} landing`);
  if (k.external) parts.push(`${k.external} in external review`);
  if (finished && k.done) parts.push(`${k.done} done`);
  if (finished && k.cancelled) parts.push(`${k.cancelled} cancelled`);
  return { ...k, text: parts.join(" · ") };
}

async function openTicket(id) {
  const t = await (await fetch(`${TASKS_API}/tickets/${id}`)).json();
  const live = (window.STATE && STATE.tickets || []).find((x) => x.id === id);
  // What needs attention comes first, before the title: a blocker, a rejection, or why it waits.
  let alerts = "";
  if (t.state === "BLOCKED") alerts += `<div class="alert blocked"><h4>Blocked · needs a decision</h4>${tasksMd(t.blocked_reason || "(no reason recorded)")}</div>`;
  if (t.state === "REJECTED" && t.feedback) alerts += `<div class="alert rejected"><h4>Rejected by ${esc(t.rejected_by || "the reviewer")} · round ${t.review_rounds}</h4>${tasksMd(t.feedback)}</div>`;
  if (live && live.state === "OPEN" && !live.ready) alerts += `<div class="alert waiting"><h4>Waiting</h4>${esc(live.why_waiting)}</div>`;
  const stateColor = color(t.state);
  const row = (k, v) => (v ? `<div>${k}</div><div class="num">${esc(v)}</div>` : "");
  openDrawer(`${alerts}<h3><span class="pill" style="--c:${stateColor};background:${stateColor}">${t.state.replace(/_/g, " ")}</span><span style="font-family:var(--mono)">${esc(t.id)}</span> ${esc(t.title)}</h3>
    <div class="kv"><div>milestone</div><div>${esc(t.milestone_id)}</div><div>priority</div><div>${priorityText(t, live)}</div><div>depends on</div><div>${t.depends_on.join(", ") || "—"}</div>
    ${row("held by", t.owner)}${row("branch", t.branch)}${row("reviewed commit", (t.reviewed_commit || "").slice(0, 10))}${row("pull request", t.pull && `${t.pull} (${t.pull_state || "?"}) at ${(t.pull_head || "").slice(0, 10)}`)}<div>worker turns</div><div>${turnsText(t)}</div>
    ${live && live.state === "OPEN" && live.ready ? `<div>waiting</div><div>${esc(live.why_waiting)}</div>` : ""}</div>
    <div id="ticket-plugins"></div>
    ${t.objective ? `<h2>Objective</h2>${tasksMd(t.objective)}` : ""}
    <h2>Description</h2>${tasksMd(t.description) || '<div class="empty">none</div>'}<h2>Acceptance</h2>${tasksMd(t.acceptance) || '<div class="empty">none</div>'}
    ${t.verification ? `<h2>Verification</h2>${tasksMd(t.verification)}` : ""}
    ${t.state !== "REJECTED" && t.feedback ? `<h2>${t.rejected_by ? "Last feedback from " + esc(t.rejected_by) : "Note for the worker"}</h2>${tasksMd(t.feedback)}` : ""}
    <h2>Notes</h2>${t.notes.slice().reverse().map((n) => `<div class="note"><b>${esc(n.author)} · ${esc(n.kind)} · ${esc(n.created_at)}</b>${tasksMd(n.text)}</div>`).join("") || '<div class="empty">none</div>'}`);
  ticketDrawerOpened(t);
}

// The ticket drawer's one extension point, for the packages that know more about a ticket than the
// task system does (the agents show the sessions that worked on it): every drawer opened is
// announced as "tasks:ticket-drawer" on document, with detail {id, ticket, mount}. `ticket` is
// the ticket as /tickets/<id> gives it; `mount` is an empty element in the drawer, under the
// ticket's fields, that a listener fills. Nothing here knows who listens.
function ticketDrawerOpened(t) {
  const mount = document.getElementById("ticket-plugins");
  if (mount) document.dispatchEvent(new CustomEvent("tasks:ticket-drawer", { detail: { id: t.id, ticket: t, mount } }));
}

function priorityText(t, live) {
  const p = live && live.priority_info; if (!p) return String(t.priority);
  const bits = [];
  if (p.inherited_from) bits.push(`inherited from ${p.inherited_from}`);
  if (p.age_levels) bits.push(`+${p.age_levels} for age`);
  return p.effective === p.own ? `${p.own}` : `${p.effective} <span class="muted">(own ${p.own}; ${bits.join(", ")})</span>`;
}

// The operator's controls, drawn by the Tasks panel from the /board
// answer D: the capacity ceilings with one-more/one-fewer buttons, and the pause. ns names the
// object (taskControlActions) the buttons call.
function taskControls(D, ns) {
  const c = (D && D.capacity) || {}, paused = !!(D && D.pickup_paused);
  const cap = (kind) => {
    const step = (d) => `<button class="ctl" style="padding:0 6px;margin:0" onclick="event.stopPropagation();${ns}.capacity('${kind}',${d})" title="${d < 0 ? "one fewer" : "one more"} ${kind.slice(0, -1)}">${d < 0 ? "−" : "+"}</button>`;
    return `<span title="how many tickets may be offered to ${kind} at once">${step(-1)}<b style="margin:0 4px">${c["max_" + kind] ?? "?"}</b>${step(1)} ${kind}</span>`;
  };
  return `${cap("workers")}${cap("reviewers")}${paused ? '<span style="color:#fde68a">new workers PAUSED</span>' : ""}<button class="ctl ${paused ? "paused" : ""}" style="margin:0" onclick="event.stopPropagation();${ns}.pause()" title="${paused ? "Resume offering work to workers." : "Stop offering new work to workers. Work under way finishes; reviews go on."}">${paused ? "▶ resume" : "⏸ pause new workers"}</button>`;
}
function taskControlActions(current, refresh) {
  const post = async (body) => {
    const r = await fetch(TASKS_API + "/control", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });
    if (!r.ok) alert(await r.text());
    refresh();
  };
  return {
    capacity(kind, d) { const c = (current() || {}).capacity || {}; const b = { action: "capacity", workers: c.max_workers, reviewers: c.max_reviewers }; b[kind] = Math.max(0, (c["max_" + kind] || 0) + d); post(b); },
    pause() { post({ action: (current() || {}).pickup_paused ? "resume" : "pause" }); },
  };
}

document.addEventListener("keydown", (e) => { if (e.key === "Escape") closeDrawer(); });

// #ticket=<id> opens the ticket's drawer.
function tasksFromHash() {
  const m = location.hash.match(/^#ticket=([^&]+)/);
  if (m) openTicket(decodeURIComponent(m[1]));
}
window.addEventListener("hashchange", tasksFromHash);

/plugins/agents/static/agents.js.body:
// The agents' shared page code: session transcripts (paged, live), the Supervisor chat, session
// chips and phases. Loaded after Orchestra's /static/app.js by the Agents page and by the agents'
// every-page scripts. Its names do not clash with the task system's tasks.js (which has the ticket
// drawers): a page may load both, and each calls the other's functions only when they are there.
const AGENTS_API = "/api/plugins/agents";

// Agent prose and human input are markdown: marked renders it, DOMPurify sanitizes it, highlight.js
// colours the code blocks. They come from cdnjs, each loaded once by whichever page loads this
// file; until they arrive md() shows the plain text. `agentsLibs` settles when they have loaded or failed.
function agentsLoad(src) {
  return new Promise((ok, bad) => { const s = document.createElement("script"); s.src = src; s.onload = ok; s.onerror = bad; document.head.appendChild(s); });
}
const AGENTS_CDN = "https://cdnjs.cloudflare.com/ajax/libs";
if (!document.querySelector(`link[href^="${AGENTS_CDN}/highlight.js/"]`)) {
  const l = document.createElement("link"); l.rel = "stylesheet"; l.href = `${AGENTS_CDN}/highlight.js/11.9.0/styles/github-dark.min.css`; document.head.appendChild(l);
}
const agentsLibs = Promise.all([
  window.marked || agentsLoad(`${AGENTS_CDN}/marked/12.0.2/marked.min.js`).catch(() => {}),
  window.DOMPurify || agentsLoad(`${AGENTS_CDN}/dompurify/3.1.6/purify.min.js`).catch(() => {}),
  window.hljs || agentsLoad(`${AGENTS_CDN}/highlight.js/11.9.0/highlight.min.js`).catch(() => {}),
]);

function md(text) {
  if (!text) return "";
  if (!(window.marked && window.DOMPurify)) return `<pre>${esc(text)}</pre>`;
  return `<div class="md">${DOMPurify.sanitize(marked.parse(text, { gfm: true, breaks: true }))}</div>`;
}
// Highlights code blocks, guessing the language when the fence does not name one.
function highlightCode(root) {
  if (!window.hljs) return;
  root.querySelectorAll("pre code").forEach((el) => {
    if (el.dataset.highlighted) return;
    const named = [...el.classList].find((c) => c.startsWith("language-"));
    if (named && hljs.getLanguage(named.slice(9))) hljs.highlightElement(el);
    else {
      const r = hljs.highlightAuto(el.textContent);
      el.innerHTML = r.value; el.classList.add("hljs", `language-${r.language || "plaintext"}`);
      el.dataset.highlighted = "yes";
    }
  });
}

// opening any drawer ends the paging of a transcript that was open in it, and highlights its code
const orchestraOpenDrawer = openDrawer;
openDrawer = function (html) { transcriptPaging = null; orchestraOpenDrawer(html); highlightCode($("drawer")); };   // eslint-disable-line no-func-assign

let transcriptPaging = null;   // {id, nextBefore, hasMore, loading}

async function openTranscript(id) {
  const r = await fetch(`${AGENTS_API}/sessions/${id}/transcript?limit=30`);
  if (!r.ok) {
    const perTicket = /^(worker|reviewer)-/.test(id);
    return openDrawer(`<h3>${esc(id)}</h3><div class="empty">${perTicket
      ? "No record of this session (" + esc(id) + "): it never ran, or it was removed."
      : "This session has not been started. It comes up with the agents' host, which <code>orchestra run</code> starts."}</div>`);
  }
  const d = await r.json(); const s = d.session;
  const perTicket = /^(worker|reviewer)-/.test(id);
  let html = `<div id="transcript-head">${transcriptHead(id, s, d)}</div>`;
  if (id === "supervisor") html += `<form id="chat" class="chat top" onsubmit="return sendToSupervisor(event)">
      <textarea id="chat-input" rows="3" placeholder="Message the Supervisor… (Enter to send, Shift+Enter for a new line)" ${s.alive ? "" : "disabled"}></textarea>
      <button type="submit" ${s.alive ? "" : "disabled"}>Send</button>
      ${s.alive ? "" : '<div class="empty">The Supervisor is reachable while the agents&#39; host is up (<code>orchestra run</code> starts it).</div>'}
    </form><div id="live"></div>`;
  if (d.started_with) html += `<details class="started"><summary>The prompt this session was started with <span class="muted">(${d.started_with.length.toLocaleString()} chars; roles, team responsibilities, where it works)</span></summary><div class="prompt md">${md(d.started_with)}</div></details>`;
  else if (!perTicket) html += `<div class="empty">The prompt file this session was started with is missing: the agents' state directory was cleaned since. The agent's current prompt is on the Agents page.</div>`;
  html += `<h2>Transcript · newest first</h2><div id="transcript">`;
  // Only markers at least as new as the oldest message on this page are placed; older ones belong to older pages.
  const oldest = d.messages.length ? Math.min(...d.messages.map(tsOf)) : 0;
  const first = withMarkers(d.messages, d.markers, d.has_more ? oldest - 1 : 0);
  html += first.length ? first.map(renderMessage).join("") : `<div class="empty">${s.file_exists ? "No messages yet." : "No turns yet: the harness creates the session file on the first prompt. This agent is woken by events or, for the Supervisor, by a message."}</div>`;
  html += `</div><div id="transcript-more" class="empty" style="margin-top:8px">${d.has_more ? "scroll for older messages…" : "beginning of session"}</div>`;
  openDrawer(html);
  transcriptPaging = { id, nextBefore: d.next_before, hasMore: d.has_more, loading: false, total: d.total,
                       markerTs: Math.max(0, ...(d.markers || []).map(tsOf)) };
  const ta = $("chat-input");
  if (ta) { ta.focus(); ta.addEventListener("keydown", (e) => { if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); $("chat").requestSubmit(); } }); }
}

function transcriptHead(id, s, d) {
  const st = agentStatus(s, Date.now() / 1000, { host_alive: d.host && d.host.alive });
  const when = (t) => (t ? new Date(t * 1000).toLocaleString() : "—");
  const perTicket = /^(worker|reviewer)-/.test(id);
  const agentLink = s.kind && !perTicket ? `<a href="/agents#agent=${encodeURIComponent(s.kind)}" class="muted" style="margin-left:auto;font-size:11px" title="The agent's definition, schedule, and every run it has made">↩ ${esc(s.kind)}: definition and all runs</a>` : "";
  // a harness that keeps a process between turns has its own pid; one that starts a process per turn has none between them
  const process = s.pid ? `pid ${s.pid} (the turn's process)` : s.alive ? "none between turns; the session is kept by the agents' host" : "none";
  const kv = `<div class="kv"><div>kind</div><div>${esc(s.kind || "")}</div><div>process</div><div>${esc(process)}</div>
    ${s.ticket_id ? `<div>ticket</div><div><a href="#" onclick="(window.openTicket ? openTicket('${esc(s.ticket_id)}') : (location.href='/tickets#ticket=${esc(s.ticket_id)}'));return false">${esc(s.ticket_id)}</a></div>` : ""}
    <div>last started</div><div>${when(s.started_at)}${s.status === "running" ? ` <span class="muted">(turn running ${ago((Date.now() / 1000) - s.started_at)})</span>` : ""}</div>
    <div>last output</div><div>${s.last_output_at ? ago((Date.now() / 1000) - s.last_output_at) + " ago" : "—"}</div>
    <div>last turn ended</div><div>${when(s.settled_at)}</div>
    <div>turns</div><div>${d.turns} · ${d.total} messages <span class="muted">· live, refreshes every ${TRANSCRIPT_POLL_MS / 1000}s</span></div><div>session file</div><div class="muted" style="word-break:break-all">${s.file_exists ? esc(s.session_file) : "(created on the first turn)"}</div></div>`;
  return `<h3>${esc(id)} <span class="chip ${st.cls}" title="${esc(st.title)}"><span class="dot"></span>${esc(st.text)}</span>${agentLink}</h3>
    ${id === "supervisor" ? `<details class="started"><summary class="muted">session details</summary>${kv}</details>` : kv}
    ${s.status === "running" && (s.partial_text || s.thinking_chars) ? `<div class="msg assistant inprogress"><div class="r">reply in progress <span class="muted">· not in the transcript until the message completes${s.thinking_chars ? ` · ${Number(s.thinking_chars).toLocaleString()} chars of thinking so far` : ""}</span></div>${s.partial_text ? md(s.partial_text) : '<span class="muted">(thinking; no reply text yet)</span>'}</div>` : ""}`;
}

const TRANSCRIPT_POLL_MS = 5000;

// The open transcript polls for what arrived since it was rendered and prepends it
// (newest first), keeping the reader's place and the older pages already loaded.
async function refreshTranscript() {
  const p = transcriptPaging;
  if (!p || p.loading || !$("overlay").classList.contains("open") || !$("transcript")) return;
  p.loading = true;
  try {
    const r = await fetch(`${AGENTS_API}/sessions/${p.id}/transcript?after=${p.total}`);
    if (!r.ok) return;
    const d = await r.json();
    if (d.total < p.total) { transcriptPaging = null; return openTranscript(p.id); }  // file replaced: start over
    const head = $("transcript-head"); if (head) head.innerHTML = transcriptHead(p.id, d.session, d);
    const fresh = withMarkers(d.messages, d.markers, p.markerTs);
    p.markerTs = Math.max(p.markerTs || 0, ...(d.markers || []).map(tsOf));
    if (!fresh.length) return;
    const box = $("transcript"), drawer = $("drawer");
    const empty = box.querySelector(".empty"); if (empty) empty.remove();
    const before = drawer.scrollHeight;
    box.insertAdjacentHTML("afterbegin", fresh.map(renderMessage).join(""));
    highlightCode(box);
    if (drawer.scrollTop > 0) drawer.scrollTop += drawer.scrollHeight - before;  // reading older messages: do not yank
    p.nextBefore += d.messages.length; p.total = d.total;
  } catch (e) { /* next tick tries again */ }
  finally { p.loading = false; }
}

async function loadOlderTranscript() {
  const p = transcriptPaging; if (!p || !p.hasMore || p.loading) return;
  p.loading = true;
  try {
    const d = await (await fetch(`${AGENTS_API}/sessions/${p.id}/transcript?before=${p.nextBefore}&limit=30`)).json();
    const box = $("transcript"); if (!box) return;
    box.insertAdjacentHTML("beforeend", d.messages.map(renderMessage).join(""));
    highlightCode(box);
    p.nextBefore = d.next_before; p.hasMore = d.has_more;
    $("transcript-more").textContent = p.hasMore ? "scroll for older messages…" : "beginning of session";
  } finally { p.loading = false; }
}
// An open transcript follows its session and pages back as the drawer scrolls. On the pages that
// load this file late (every page but the Agents page: attention.js and machine-cards.js load it
// on demand, after the page has loaded) DOMContentLoaded has passed, so it starts at once there.
function agentsFollowTranscripts() {
  $("drawer").addEventListener("scroll", () => { const el = $("drawer"); if (transcriptPaging && el.scrollTop + el.clientHeight > el.scrollHeight - 300) loadOlderTranscript(); });
  setInterval(refreshTranscript, TRANSCRIPT_POLL_MS);
}
if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", agentsFollowTranscripts);
else agentsFollowTranscripts();

async function sendToSupervisor(ev) {
  ev.preventDefault();
  const ta = $("chat-input"), btn = ev.target.querySelector("button"), live = $("live");
  const message = ta.value.trim();
  if (!message) return false;
  ta.value = ""; ta.disabled = true; btn.disabled = true;
  live.insertAdjacentHTML("afterbegin", `<div class="msg assistant"><div class="r">supervisor · working…</div><div id="live-body"></div></div><div class="msg user"><div class="r">you</div>${md(message)}</div>`);
  highlightCode(live); $("drawer").scrollTop = 0;
  try {
    const resp = await fetch(AGENTS_API + "/supervisor", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ message }) });
    if (!resp.ok) {
      const body = await resp.text();
      const proxy = /^\s*<!doctype html|<html/i.test(body);
      $("live-body").innerHTML = `<div class="bad">${proxy ? `The connection was closed by the proxy in front of this page (HTTP ${resp.status}). The Supervisor is still working on your message; its reply will appear in the transcript below.` : esc(body.slice(0, 300))}</div>`;
      return false;
    }
    const reader = resp.body.getReader(); const dec = new TextDecoder(); let buf = "";
    while (true) {
      const { value, done } = await reader.read(); if (done) break;
      buf += dec.decode(value, { stream: true });
      let nl; while ((nl = buf.indexOf("\n")) >= 0) {
        const line = buf.slice(0, nl); buf = buf.slice(nl + 1); if (!line.trim()) continue;
        const e = JSON.parse(line); const body = $("live-body");
        if (e.type === "tool_start") body.innerHTML += `<div class="tc"><div class="r">⚙ ${esc(e.name || "tool")}</div></div>`;
        else if (e.type === "assistant_end") {
          const txt = e.text || "";
          if (txt.trim()) { body.innerHTML += md(txt); highlightCode(body); }
        } else if (e.type === "done") {
          body.previousElementSibling.textContent = e.error ? "supervisor · failed" : e.timed_out ? "supervisor · timed out" : "supervisor";
          if (e.error) body.innerHTML += `<div class="bad">${md(e.error)}</div>`;
        }
      }
    }
  } catch (err) { $("live-body").innerHTML += `<div class="bad">${esc(String(err))}</div>`; return false; }
  finally { ta.disabled = false; btn.disabled = false; ta.focus(); }
  await refreshTranscript();   // the exchange is in the session file now; show it once, there
  live.innerHTML = "";
  return false;
}

const SHELL_TOOLS = new Set(["bash", "shell", "sh", "powershell"]);

function renderToolCall(t) {
  const args = t.args && typeof t.args === "object" ? t.args : {};
  if (SHELL_TOOLS.has(t.name) && typeof args.command === "string")
    return `<div class="tc"><div class="r">⚙ ${esc(t.name)}</div><pre><code class="language-bash">${esc(args.command)}</code></pre></div>`;
  const shown = Object.keys(args).length ? JSON.stringify(args, null, 1) : (typeof t.args === "string" ? t.args : "");
  return `<div class="tc"><div class="r">⚙ ${esc(t.name)}</div>${shown ? `<pre><code class="language-json">${esc(shown).slice(0, 3000)}</code></pre>` : ""}</div>`;
}

function msgTime(m) {
  if (!m.ts) return "";
  // a harness may record timestamps as ISO strings or epoch millis (or seconds).
  const t = typeof m.ts === "number" ? (m.ts > 1e12 ? m.ts : m.ts * 1000) : Date.parse(m.ts);
  if (!isFinite(t)) return "";
  return `<span class="muted num" style="margin-left:8px">${new Date(t).toLocaleTimeString()} · ${ago((Date.now() - t) / 1000)} ago</span>`;
}
const tsOf = (m) => { const t = typeof m.ts === "number" ? (m.ts > 1e12 ? m.ts : m.ts * 1000) : Date.parse(m.ts || ""); return isFinite(t) ? t : 0; };
function fmtDur(s) { return s == null ? "" : s >= 3600 ? `${Math.floor(s / 3600)}h ${Math.round((s % 3600) / 60)}m` : s >= 60 ? `${Math.floor(s / 60)}m ${Math.round(s % 60)}s` : `${Math.round(s)}s`; }
function renderMarker(e) {
  let text;
  if (e.type === "session.timed_out" && e.stopped_by === "silence") text = `⏱ Orchestra stopped this turn: nothing came from the agent for ${fmtDur(e.limit)} (silence_timeout) while it was ${esc(e.doing || "working")}` +
    (e.phase_for != null ? `, ${fmtDur(e.phase_for)} into that` : "") + ". Orchestra took that as stuck. If the model was only slow, raise silence_timeout in orchestra.toml.";
  else if (e.type === "session.timed_out") text = `⏱ Orchestra stopped this turn: the ${fmtDur(e.limit)} hard turn limit (turn_timeout in orchestra.toml) ran out while the agent was ${esc(e.doing || "working")}` +
    (e.phase_for != null ? ` (${fmtDur(e.phase_for)} into that)` : "") + (e.silent_for != null ? `, last output ${fmtDur(e.silent_for)} earlier` : "") + ". Nothing after this point was the agent's decision.";
  else if (e.type === "session.error") text = `✖ Orchestra ended this turn: ${md(e.error || "harness error")}`;
  else if (e.type === "session.interrupted") text = `■ Orchestra was restarted or stopped during this turn, which cut it off. ${esc(e.reason || "")}`;
  else if (e.type === "agent.crashed") text = `✖ The agent's process exited on its own between turns (crash ${e.count || 1}); Orchestra is restarting it.${e.stderr ? ` Last stderr: <code>${esc(e.stderr.trim().split("\n").slice(-1)[0].slice(0, 160))}</code>` : ""}`;
  else if (e.type === "agent.crash_loop") text = `✖ Crash loop: ${e.count} exits in fifteen minutes. The agent is paused after a crash loop and the Supervisor has been asked to look: ask the Supervisor to resume it once fixed.`;
  else if (e.type === "agent.compacted") text = `⇣ Context compacted by the harness${e.tokens_before ? `: ${Number(e.tokens_before).toLocaleString()}${e.tokens_after ? ` → ${Number(e.tokens_after).toLocaleString()}` : ""} tokens` : ""} (${esc(e.reason || "")}). Older messages became a summary the agent keeps; the transcript is unchanged.`;
  else if (e.type === "agent.reset") text = `⟲ Session started over by ${esc(e.by || "the Supervisor")}${e.reason ? ` (${esc(e.reason)})` : ""}. The conversation before this point is archived as run <code>${esc(e.archived || "")}</code>; the agent keeps the project context and its team's space, not its memory of the chat.`;
  else if (e.type === "agent.corrected") text = `✎ ${md(e.text || "")}`;
  else if (e.type === "session.started") text = `▶ Turn started${e.ticket ? " on " + esc(e.ticket) : ""}.`;
  else text = esc(e.type);
  return `<div class="msg marker ${e.type}"><div class="r">orchestra${msgTime({ ts: e.ts })}</div>${text}</div>`;
}
// Markers are Orchestra's events for the session; they are merged with the messages by time, newest first.
function withMarkers(messages, markers, newerThan) {
  const ms = (markers || []).filter((e) => tsOf(e) > (newerThan || 0)).map((e) => ({ ...e, _marker: true }));
  return [...messages, ...ms].sort((a, b) => tsOf(b) - tsOf(a));
}
// A user message that Orchestra wrote: a wake-up, an assignment, a review request, a nudge.
const FROM_ORCHESTRA = /^(\[Orchestra:|# Wake-up for |# Your assignment|# Review request|You stopped without)/;
// The Supervisor's prompt is the context Orchestra put in front (leading `[Orchestra: ...]` blocks:
// the project context document, the events since its last turn, the ticket counts) and then the
// human's words. The last block is either the one-line counts or the context document, which
// ends at the last blank line before the human's words.
function splitSupervisorPrompt(text) {
  if (!text.startsWith("[Orchestra:") || /^\[Orchestra: escalation/.test(text) || /\n# Wake-up for /.test(text)) return null;
  const lines = text.split("\n");
  let last = -1;
  lines.forEach((ln, i) => { if (ln.startsWith("[Orchestra:")) last = i; });
  let cut = last + 1;
  if (!/^\[Orchestra: ticket counts now/.test(lines[last])) { cut = lines.length; while (cut > last + 1 && lines[cut - 1] !== "") cut--; }
  while (cut < lines.length && lines[cut] === "") cut++;
  if (cut >= lines.length) return null;
  const context = lines.slice(0, cut).join("\n").trimEnd();
  return { context, contextLines: context.split("\n").length, human: lines.slice(cut).join("\n") };
}
// A wake-up is Orchestra's prompt to an agent the human did not write: what woke it, then the
// whole project snapshot. In a transcript it is one line, the reasons, with the prompt folded under
// it, so what the agent answered is what the eye lands on.
function wakeReasons(text) {
  const at = text.indexOf("## Why you were woken");
  if (at < 0) return [];
  return text.slice(at).split("\n## ")[0].split("\n").filter((l) => l.startsWith("- ")).map((l) => l.slice(2).trim()).filter(Boolean);
}
function renderWake(m) {
  const who = (m.text.match(/# Wake-up for the ([^\n]+)/) || [])[1] || "agent";
  const why = wakeReasons(m.text), first = why.slice(0, 2).map((r) => esc(r.slice(0, 160))).join("; ") || "an event";
  return `<details class="msg marker wake"${m.i != null ? ` data-i="${m.i}"` : ""}><summary><b>Orchestra woke the ${esc(who)}</b>, not a message from you: ${first}${why.length > 2 ? ` · and ${why.length - 2} more` : ""}${msgTime(m)}</summary>
    <div class="prompt md">${md(m.text.slice(0, 12000))}</div></details>`;
}
function renderMessage(m) {
  if (m._marker) return renderMarker(m);
  const at = m.i != null ? ` data-i="${m.i}"` : "";
  if (m.role === "toolResult") {
    const shell = SHELL_TOOLS.has(m.tool_name);
    const body = shell ? `<pre class="term">${highlightLog(m.text)}</pre>` : `<pre><code>${esc(m.text)}</code></pre>`;
    return `<div class="msg toolResult ${m.is_error ? "err" : ""}"${at}><div class="r">result · ${esc(m.tool_name || "tool")}${m.is_error ? ' <span class="bad">error</span>' : ""}${msgTime(m)}</div>${body}</div>`;
  }
  if (m.role === "user") {
    if (m.text.startsWith("# Wake-up for ") || (m.text.startsWith("[Orchestra:") && m.text.includes("\n# Wake-up for "))) return renderWake(m);
    const split = splitSupervisorPrompt(m.text);
    if (split) return `<details class="msg marker context"><summary>context the Supervisor was given (${split.contextLines} lines)</summary><div class="prompt md">${md(split.context.slice(0, 12000))}</div></details>
      <div class="msg user"${at}><div class="r">you${msgTime(m)}</div>${md(split.human.slice(0, 12000))}</div>`;
    const who = FROM_ORCHESTRA.test(m.text) ? "orchestra" : "you";
    return `<div class="msg user"${at}><div class="r">${who}${msgTime(m)}</div>${md(m.text.slice(0, 12000))}</div>`;
  }
  return `<div class="msg ${m.role}"${at}><div class="r">${m.role}${msgTime(m)}</div>${md(m.text.slice(0, 12000))}${m.tool_calls.map(renderToolCall).join("")}</div>`;
}

// One turn of a session, in order, for reading at a glance (the ticket drawer's agent sessions,
// ticket-sessions.js): the prompt folded to its first line, what the agent wrote, each tool call
// folded to its name and gist with its result inside, the host's stops, and the last words open.
function toolGist(c) {
  const a = c.args && typeof c.args === "object" ? c.args : {};
  const v = a.command || a.path || a.file_path || a.state || a.verdict || a.message || a.summary || a.pattern || a.query || "";
  return typeof v === "string" ? v.split("\n")[0].slice(0, 90) : "";
}
function renderTurn(msgs, markers) {
  const out = [];
  const lastText = [...msgs].reverse().find((m) => m.role === "assistant" && m.text.trim());
  const pending = [];   // tool results waiting for the call they answer: in order, one per call
  msgs.forEach((m) => {
    if (m.role === "user") {
      const first = m.text.split("\n").find((l) => l.trim() && !l.startsWith("[Orchestra:")) || m.text.split("\n")[0];
      out.push(`<details class="tt-prompt"><summary><span class="muted">${FROM_ORCHESTRA.test(m.text) ? "prompt" : "message"}${msgTime(m)}</span> ${esc(first.replace(/^#+\s*/, "").slice(0, 140))}</summary><div class="prompt md">${md(m.text.slice(0, 12000))}</div></details>`);
    } else if (m.role === "assistant") {
      if (m.text.trim()) out.push(`<div class="tt-say ${m === lastText ? "last" : ""}">${md(m.text.slice(0, 12000))}</div>`);
      (m.tool_calls || []).forEach((c) => { const slot = { c, res: null }; pending.push(slot); out.push(slot); });
    } else if (m.role === "toolResult") {
      const slot = pending.find((x) => !x.res && (x.c.name === m.tool_name || m.tool_name === "?")) || pending.find((x) => !x.res);
      if (slot) slot.res = m; else out.push({ c: { name: m.tool_name || "tool", args: {} }, res: m });
    }
  });
  const html = out.map((x) => {
    if (typeof x === "string") return x;
    const { c, res } = x, gist = toolGist(c), err = res && res.is_error;
    const shown = c.args && typeof c.args === "object" && Object.keys(c.args).length ? JSON.stringify(c.args, null, 1) : "";
    return `<details class="tt-tool ${err ? "err" : ""}"><summary>⚙ <b>${esc(c.name)}</b>${gist ? ` <code>${esc(gist)}</code>` : ""}${res ? (err ? ' <span class="bad">error</span>' : "") : ' <span class="muted">· no result yet</span>'}</summary>
      ${shown ? `<pre><code class="language-json">${esc(shown.slice(0, 3000))}</code></pre>` : ""}${res ? `<div class="r muted">result</div><pre class="term">${esc((res.text || "(empty)").slice(0, 6000))}</pre>` : ""}</details>`;
  });
  (markers || []).forEach((e) => html.push(renderMarker(e)));
  return html.join("") || '<div class="empty">No messages in this turn yet.</div>';
}

document.addEventListener("keydown", (e) => { if (e.key === "Escape") closeDrawer(); });

// #session=<id> opens a transcript (the task system's tasks.js handles #ticket= and #gate=)
function agentsFromHash() {
  const m = location.hash.match(/^#session=([^&]+)/);
  if (m) openTranscript(decodeURIComponent(m[1]));
}
window.addEventListener("hashchange", agentsFromHash);

// The one source of an agent's status text: `s` is its latest session (or null), `a` what is
// known of the agent beyond its session (resident, name, next_scheduled_at, host_alive), when
// known. A per-ticket role or an ephemeral agent with nothing running is idle, never down; down
// is a resident whose host is gone; a resident between turns says what it waits for.
function agentStatus(s, now, a) {
  a = a || {};
  if (s && s.status === "archived") return { cls: "archived", text: "finished", title: "ticket closed" };
  if (s && s.status === "running") return runningPhase(s, now);
  const perTicket = s ? (!!s.ticket_id || /^(worker|reviewer)-/.test(s.id || s.session || "")) : false;
  const resident = a.resident != null ? a.resident : !perTicket && !!s;
  if (!resident) {
    const last = s && s.settled_at ? `last run ${ago(now - s.settled_at)} ago` : "no run yet";
    return { cls: "", text: "idle", title: s && s.last_text ? `${last}: ${s.last_text.slice(0, 160)}` : last };
  }
  if (a.host_alive === false || !(s && s.alive)) return { cls: "down", text: "down", title: "the agents' host (agents.host, started by orchestra run) is not up" };
  const name = a.name || (s && s.kind);
  const title = name === "supervisor" ? "waiting for your message" + (a.next_review_at && a.next_review_at > now ? `; next review in ${ago(a.next_review_at - now)}` : "") : a.next_scheduled_at ? `next wake-up in ${ago(a.next_scheduled_at - now)}` : "waiting for an event";
  return { cls: "resident", text: "resident", title };
}
function runningPhase(s, now) {
  const age = (t) => ago(now - (t || now));
  const turn = `turn started ${age(s.started_at)} ago`;
  if (s.phase === "tool") return { cls: "working", text: `running ${s.tool_name || "tool"} · ${age(s.phase_since)}`, title: turn };
  if (s.phase === "generating") {
    const sinceTok = s.last_token_at ? now - s.last_token_at : 0;
    return { cls: sinceTok > 60 ? "waiting" : "working", text: `receiving tokens · last token ${ago(sinceTok)} ago`, title: turn };
  }
  // The session is mid-turn and its stream has been quiet since phase_since: normal while a
  // tool runs or the model thinks; past a minute it is worth saying how long.
  const wait = now - (s.phase_since || s.started_at || now);
  if (wait <= 60) return { cls: "working", text: `working · ${ago(wait)}`, title: `${turn}; quiet since then, which is normal while a tool runs` };
  return { cls: "waiting", text: `quiet for ${ago(wait)}`, title: `the turn is still running; no output for ${ago(wait)}` };
}
function sessionChip(s, now, a) {
  const p = agentStatus(s, now, a);
  return `<span class="chip ${p.cls}" title="${esc(p.title)}"><span class="dot"></span>${esc(p.text)}</span>`;
}

